const BROWSER_AUDIO_EXTENSIONS = /\.(mp3|flac|m4a|wav|ogg|opus|aac)$/i;
const ELECTRON_FALLBACK_AUDIO_EXTENSIONS = /\.(alac|ape|wv|tta|wma|aif|aiff|caf)$/i;
const KNOWN_AUDIO_EXTENSIONS = /\.(mp3|flac|m4a|wav|ogg|opus|aac|alac|ape|wv|tta|wma|aif|aiff|caf)$/i;
const LYRIC_EXTENSIONS = /\.(lrc|vtt|ttml|qrc|yrc|krc|fia)$/i;
const TRANSLATION_LYRIC_EXTENSIONS = /\.t\.(lrc|vtt)$/i;
const IMPORT_CONCURRENCY = 6;
export const LOCAL_MUSIC_UPDATED_EVENT = 'folia-local-music-updated';
export const LOCAL_MUSIC_SCAN_PROGRESS_EVENT = 'folia-local-music-scan-progress';
const HYDRATION_BATCH_SIZE = 25;
const HYDRATION_REFRESH_EVERY = 100;
const SNAPSHOT_HASH_SEED = 2166136261;
const REIMPORT_HANDLE_MISSING_ERROR = 'Missing persisted directory handle for reimport';
const PREFERRED_FOLDER_COVER_FILES = ['cover.png', 'cover.jpg', 'cover.jpeg'];

export interface LocalMusicScanProgressDetail {
    active: boolean;
    folderName: string;
    phase?: 'discovering' | 'importing' | 'hydrating' | 'completed' | 'cancelled' | 'error';
    totalSongs: number;
    completedSongs: number;
    discoveredSongs?: number;
    processedSongs?: number;
    skippedSongs?: number;
    failedSongs?: number;
    cancelled?: boolean;
}

let activeScanProgress: LocalMusicScanProgressDetail | null = null;
let globalScanCancelEpoch = 0;
const cancelledScanRoots = new Map<string, number>();
const inFlightRootImports = new Map<string, Promise<LocalSong[]>>();

export function getActiveLocalMusicScanProgress(): LocalMusicScanProgressDetail | null {
    return activeScanProgress;
}

export function cancelLocalLibraryScan(rootFolderName?: string): void {
    if (rootFolderName) {
        const normalized = rootFolderName.split('/')[0] || rootFolderName;
        cancelledScanRoots.set(normalized, (cancelledScanRoots.get(normalized) || 0) + 1);
    } else {
        globalScanCancelEpoch += 1;
        if (activeScanProgress?.folderName) {
            const normalized = activeScanProgress.folderName.split('/')[0] || activeScanProgress.folderName;
            cancelledScanRoots.set(normalized, (cancelledScanRoots.get(normalized) || 0) + 1);
        }
    }
    if (activeScanProgress && activeScanProgress.active) {
        const nextDetail: LocalMusicScanProgressDetail = {
            ...activeScanProgress,
            active: false,
            phase: 'cancelled',
            cancelled: true,
        };
        activeScanProgress = nextDetail;
        window.dispatchEvent(new CustomEvent(LOCAL_MUSIC_SCAN_PROGRESS_EVENT, { detail: nextDetail }));
    }
}

export function isLocalLibraryScanCancelled(
    rootFolderName: string,
    startedGlobalEpoch: number,
    startedRootEpoch: number,
): boolean {
    const normalized = rootFolderName.split('/')[0] || rootFolderName;
    return globalScanCancelEpoch !== startedGlobalEpoch
        || (cancelledScanRoots.get(normalized) || 0) !== startedRootEpoch;
}

function formatImportDuration(ms: number): string {
    if (ms < 1000) {
        return `${ms.toFixed(1)}ms`;
    }

    return `${(ms / 1000).toFixed(2)}s`;
}

function notifyLocalMusicUpdated() {
    window.dispatchEvent(new CustomEvent(LOCAL_MUSIC_UPDATED_EVENT));
}

async function removeDeletedSongIdsFromPlaylists(songIds: string[]): Promise<void> {
    if (songIds.length === 0) {
        return;
    }

    const removingIds = new Set(songIds);
    const playlists = await getLocalPlaylists();
    let changed = false;
    const nextPlaylists = playlists.map(playlist => {
        const nextSongIds = playlist.songIds.filter(songId => !removingIds.has(songId));
        if (nextSongIds.length === playlist.songIds.length) {
            return playlist;
        }

        changed = true;
        return {
            ...playlist,
            songIds: nextSongIds,
        };
    });

    if (changed) {
        await saveLocalPlaylists(nextPlaylists);
    }
}

function notifyLocalMusicScanProgress(detail: LocalMusicScanProgressDetail) {
    activeScanProgress = detail;
    window.dispatchEvent(new CustomEvent(LOCAL_MUSIC_SCAN_PROGRESS_EVENT, { detail }));
}

async function getImportDirectoryHandle(expectedRootName?: string): Promise<FileSystemDirectoryHandle | null> {
    if (expectedRootName) {
        const dirHandles = await getDirHandles();
        const persistedHandle = dirHandles[expectedRootName];

        if (!persistedHandle) {
            throw new Error(REIMPORT_HANDLE_MISSING_ERROR);
        }

        const permissionAwareHandle = persistedHandle as FileSystemDirectoryHandle & {
            queryPermission: (descriptor: { mode: 'read' | 'readwrite'; }) => Promise<PermissionState>;
            requestPermission: (descriptor: { mode: 'read' | 'readwrite'; }) => Promise<PermissionState>;
        };

        let permission = await permissionAwareHandle.queryPermission({ mode: 'read' });
        if (permission !== 'granted') {
            permission = await permissionAwareHandle.requestPermission({ mode: 'read' });
        }

        if (permission !== 'granted') {
            return null;
        }

        return persistedHandle;
    }

    const availability = getLocalLibraryAvailability();
    if (!availability.supported) throw new Error(`Local library unavailable: ${availability.reason}`);

    if (hasFoliaAndroidBridge()) {
        return await pickAndroidDirectoryHandle();
    }

    // @ts-ignore - showDirectoryPicker is not in all TypeScript definitions
    return await window.showDirectoryPicker();
}

async function findImportedRootForHandle(dirHandle: FileSystemDirectoryHandle): Promise<string | null> {
    const dirHandles = await getDirHandles();
    const selectedHandle = dirHandle as FileSystemDirectoryHandle & {
        isSameEntry?: (other: FileSystemHandle) => Promise<boolean>;
    };

    if (!selectedHandle.isSameEntry) {
        return null;
    }

    for (const [rootFolderName, persistedHandle] of Object.entries(dirHandles)) {
        try {
            if (await selectedHandle.isSameEntry(persistedHandle)) {
                return rootFolderName;
            }
        } catch (error) {
            console.warn(`[LocalMusic][Import] Failed to compare imported directory with "${rootFolderName}":`, error);
        }
    }

    return null;
}

// Generate UUID for local songs
function generateId(): string {
    return `local_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

// Extract basic metadata from filename.
// Expected format: "Artist - Title.mp3", "Artist-Title.mp3", or "Title.mp3".
export function extractMetadataFromFilename(fileName: string): { title?: string; artist?: string; } {
    // 去掉扩展名
    let nameWithoutExt = fileName.replace(KNOWN_AUDIO_EXTENSIONS, '');

    // Strip common downloader site watermarks like [MaTb3aA.CoM], (Sm3na.com), (320 kbps), etc.
    nameWithoutExt = nameWithoutExt
        .replace(/\s*\[(?:[^\]]*(?:\.(?:com|net|org|me|io|cc)|\b(?:mp3|kbps|official|matb3aa|sm3na|dandanha|nogomi|arab|mawaly)\b)[^\]]*)\]/gi, '')
        .replace(/\s*\((?:[^)]*(?:\.(?:com|net|org|me|io|cc)|\b(?:320\s*kbps|128\s*kbps|official\s+audio|official\s+lyric\s+video|matb3aa|sm3na|dandanha|nogomi|mawaly)\b)[^)]*)\)/gi, '')
        .trim();

    // 去掉开头的cue切分产生的序号 "01. ", "01 - ", or "1-01 " 
    nameWithoutExt = nameWithoutExt.replace(/^\d{1,3}(?:[-.]\d{1,3})?(?:\s*[-.]\s*|\s+)/, '');

    // 分割艺术家和标题 - 尝试 " - " / " – " / " — " (带空格)
    const spacedParts = nameWithoutExt.split(/\s+[-–—]\s+/);
    if (spacedParts.length === 2) {
        return {
            artist: spacedParts[0].trim(),
            title: spacedParts[1].trim()
        };
    }

    // 尝试 "-" (不带空格) - 但要确保不是单词中间的连字符
    // 我们检查最后一个"-"是否可能是分隔符
    const lastDashIndex = nameWithoutExt.lastIndexOf('-');
    if (lastDashIndex > 0 && lastDashIndex < nameWithoutExt.length - 1) {
        const potentialTitle = nameWithoutExt.substring(0, lastDashIndex).trim();
        const potentialArtist = nameWithoutExt.substring(lastDashIndex + 1).trim();

        // 如果分割后的两部分都有内容，使用这个分割
        if (potentialTitle && potentialArtist) {
            return {
                artist: potentialArtist,
                title: potentialTitle
            };
        }
    }

    return {
        title: nameWithoutExt.trim()
    };
}

/**
 * Automatically detects and repairs swapped Title <-> Artist fields across a folder or library
 * (e.g., when files are named "Song Title - Artist Name.mp3" or tagged with the Artist name in
 * TIT2 and the Song Title in TPE1, causing 2+ tracks to have the same artist name as their
 * `title` such as "Amr Diab" while their unique track titles sit in `artistNames` such as
 * "Al Leila", "Allem Alby", "Amaken El Sahar"), and propagates known album names across tracks
 * that share the exact same embedded album cover hash (`localCoverAssetId`).
 */
export function repairSwappedTitleArtistAndAlbumMetadata(
    targetSongs: LocalSong[],
    contextSongs?: readonly LocalSong[],
): LocalSong[] {
    if (targetSongs.length === 0) return [];
    const pool: readonly LocalSong[] = contextSongs && contextSongs.length > 0
        ? contextSongs
        : targetSongs;

    const norm = (value: string | undefined): string =>
        (value || '').normalize('NFKC').trim().replace(/\s+/gu, ' ').toLowerCase();

    const byNormTitle = new Map<string, LocalSong[]>();
    const artistFrequency = new Map<string, number>();
    const knownFolderTokens = new Set<string>();

    for (const song of pool) {
        const rawTitle = (song.importedMetadata?.title || song.title || '').trim();
        const rawArtist = (song.importedMetadata?.artistNames || []).filter(Boolean).join(', ').trim();
        const nt = norm(rawTitle);
        const na = norm(rawArtist);
        if (nt) {
            const list = byNormTitle.get(nt);
            if (list) list.push(song);
            else byNormTitle.set(nt, [song]);
        }
        if (na && na !== 'unknown artist') {
            artistFrequency.set(na, (artistFrequency.get(na) || 0) + 1);
        }
        if (song.albumArtist) {
            const naa = norm(song.albumArtist);
            if (naa) artistFrequency.set(naa, (artistFrequency.get(naa) || 0) + 2);
        }
        if (song.folderName) {
            for (const seg of song.folderName.split('/')) {
                const ns = norm(seg);
                if (ns && ns.length >= 2) knownFolderTokens.add(ns);
            }
        }
    }

    const titlesThatAreActuallyArtists = new Set<string>();
    for (const [nt, group] of byNormTitle.entries()) {
        if (group.length < 2) continue;
        const distinctArtists = new Set<string>();
        let singleOccurrenceArtists = 0;
        for (const song of group) {
            const rawArtist = (song.importedMetadata?.artistNames || []).filter(Boolean).join(', ').trim();
            const na = norm(rawArtist);
            if (na && na !== nt && na !== 'unknown artist') {
                distinctArtists.add(na);
                if ((artistFrequency.get(na) || 0) <= 2) {
                    singleOccurrenceArtists++;
                }
            }
        }
        // If >= 3 tracks share the exact same title while having >= 3 distinct artist strings,
        // or >= 2 tracks share the same title and at least 2 have unique 1-off "artist" strings
        // (or the repeated title matches a folder name / known artist), the title & artist are swapped.
        if (
            distinctArtists.size >= 3
            || (distinctArtists.size >= 2 && (singleOccurrenceArtists >= 2 || knownFolderTokens.has(nt) || (artistFrequency.get(nt) || 0) >= 2))
        ) {
            titlesThatAreActuallyArtists.add(nt);
        }
    }

    // Build shared cover hash -> consensus album name map
    const coverAlbums = new Map<string, Map<string, string>>();
    for (const song of pool) {
        const assetId = song.localCoverAssetId;
        if (!assetId || !assetId.startsWith('sha256:') || song.localCoverSource === 'folder') continue;
        const album = (song.importedMetadata?.albumName || song.onlineMetadata?.album?.name || '').trim();
        const normAlbum = norm(album);
        if (!normAlbum || normAlbum === 'unknown album') continue;
        let mapForCover = coverAlbums.get(assetId);
        if (!mapForCover) {
            mapForCover = new Map<string, string>();
            coverAlbums.set(assetId, mapForCover);
        }
        if (!mapForCover.has(normAlbum)) {
            mapForCover.set(normAlbum, album);
        }
    }
    const consensusAlbumByCover = new Map<string, string>();
    for (const [assetId, albumMap] of coverAlbums.entries()) {
        if (albumMap.size === 1) {
            const [onlyAlbum] = albumMap.values();
            if (onlyAlbum) consensusAlbumByCover.set(assetId, onlyAlbum);
        }
    }

    const modifiedSongs: LocalSong[] = [];
    for (const song of targetSongs) {
        let changed = false;
        const rawTitle = (song.importedMetadata?.title || song.title || '').trim();
        const rawArtists = (song.importedMetadata?.artistNames || []).map(a => a.trim()).filter(Boolean);
        const joinedArtist = rawArtists.join(', ').trim();
        const nt = norm(rawTitle);
        const na = norm(joinedArtist);

        const shouldSwap = Boolean(
            nt
            && na
            && nt !== na
            && na !== 'unknown artist'
            && (
                titlesThatAreActuallyArtists.has(nt)
                || (
                    (artistFrequency.get(nt) || 0) >= 3
                    && (artistFrequency.get(na) || 0) <= 1
                    && (byNormTitle.get(nt)?.length || 0) >= 1
                )
            )
        );

        if (shouldSwap) {
            const newTitle = joinedArtist;
            const newArtists = rawTitle
                .split(/[;；/／]/u)
                .map(part => part.trim())
                .filter(Boolean);
            song.importedMetadata = {
                ...song.importedMetadata,
                title: newTitle,
                artistNames: newArtists.length > 0 ? newArtists : [rawTitle],
            };
            if (song.titleOrigin === 'import' || !song.titleOrigin) {
                song.title = newTitle;
            }
            changed = true;
        }

        // Propagate consensus album name from shared embedded cover assetId when albumName is missing
        const currentAlbum = (song.importedMetadata?.albumName || '').trim();
        if (!currentAlbum && song.localCoverAssetId && consensusAlbumByCover.has(song.localCoverAssetId)) {
            song.importedMetadata = {
                ...song.importedMetadata,
                albumName: consensusAlbumByCover.get(song.localCoverAssetId),
            };
            changed = true;
        }

        if (changed) {
            modifiedSongs.push(song);
        }
    }

    return modifiedSongs;
}

// Get audio duration from file
async function getAudioDuration(file: File): Promise<number> {
    const playbackInput = await repairFlacMetadata(file, true);
    return new Promise((resolve) => {
        const audio = new Audio();
        const url = createSafeObjectUrl(playbackInput);
        if (!url) {
            resolve(0);
            return;
        }

        audio.addEventListener('loadedmetadata', () => {
            const duration = audio.duration * 1000; // Convert to milliseconds
            URL.revokeObjectURL(url);
            resolve(duration);
        });

        audio.addEventListener('error', () => {
            URL.revokeObjectURL(url);
            resolve(0); // Default duration on error
        });

        audio.src = url;
    });
}

function canImportElectronFallbackAudio(): boolean {
    return (typeof window !== 'undefined' && typeof window.electron?.requestTranscodeFallback === 'function')
        || hasFoliaAndroidBridge();
}

function isAudioFile(file: File): boolean {
    return BROWSER_AUDIO_EXTENSIONS.test(file.name)
        || (canImportElectronFallbackAudio() && ELECTRON_FALLBACK_AUDIO_EXTENSIONS.test(file.name));
}

function isAudioFileName(fileName: string): boolean {
    return BROWSER_AUDIO_EXTENSIONS.test(fileName)
        || (canImportElectronFallbackAudio() && ELECTRON_FALLBACK_AUDIO_EXTENSIONS.test(fileName));
}

function getFolderCoverPriority(fileName: string): number {
    return PREFERRED_FOLDER_COVER_FILES.indexOf(fileName.toLowerCase());
}

function getParentRelativePath(relativePath: string): string {
    const lastSlashIndex = relativePath.lastIndexOf('/');
    return lastSlashIndex === -1 ? '' : relativePath.slice(0, lastSlashIndex);
}

function getAudioBasePath(relativePath: string): string {
    return relativePath.replace(KNOWN_AUDIO_EXTENSIONS, '');
}

function getSidecarLyricBasePath(relativePath: string, kind: 'lyric' | 'translationLyric'): string {
    const withoutLyricSuffix = kind === 'translationLyric'
        ? relativePath.replace(/\.t\.(lrc|vtt)$/i, '')
        : relativePath.replace(/\.(lrc|vtt|ttml|qrc|yrc|krc|fia)$/i, '');

    // Support both "track.lrc" and "track.mp3.lrc" style sidecar lyrics.
    return getAudioBasePath(withoutLyricSuffix);
}

// Sidecar lyric base paths whose winning file differs between two format orders. Only these
// tracks need their lyrics re-read after the user reorders formats.
function collectLyricBasePathsAffectedByFormatOrder(
    files: LocalLibrarySnapshotFile[],
    previousOrder: readonly LocalLyricFileFormat[],
    nextOrder: readonly LocalLyricFileFormat[],
): Set<string> {
    const pickWinners = (order: readonly LocalLyricFileFormat[]) => {
        const winners = new Map<string, { relativePath: string; priority: number; }>();
        files.forEach((file) => {
            if (file.kind !== 'lyric' && file.kind !== 'translationLyric') {
                return;
            }
            const key = `${file.kind}:${getSidecarLyricBasePath(file.relativePath, file.kind)}`;
            const priority = getLocalLyricFilePriority(file.name, order);
            const existing = winners.get(key);
            if (!existing || priority < existing.priority) {
                winners.set(key, { relativePath: file.relativePath, priority });
            }
        });
        return winners;
    };

    const previousWinners = pickWinners(previousOrder);
    const affected = new Set<string>();
    pickWinners(nextOrder).forEach((winner, key) => {
        if (previousWinners.get(key)?.relativePath !== winner.relativePath) {
            affected.add(key.slice(key.indexOf(':') + 1));
        }
    });
    return affected;
}

function getSnapshotFileKind(fileName: string): LocalLibrarySnapshotFile['kind'] {
    const lowerName = fileName.toLowerCase();
    if (TRANSLATION_LYRIC_EXTENSIONS.test(lowerName)) {
        return 'translationLyric';
    }
    if (LYRIC_EXTENSIONS.test(lowerName)) {
        return 'lyric';
    }
    if (getFolderCoverPriority(lowerName) !== -1) {
        return 'cover';
    }
    if (isAudioFileName(fileName)) {
        return 'audio';
    }
    if (isAlbumVideoFileName(fileName)) {
        return 'video';
    }
    return 'other';
}

function buildFileSignature(relativePath: string, size: number, lastModified: number): string {
    return `${relativePath}::${size}::${lastModified}`;
}

function hashString(input: string): string {
    let hash = SNAPSHOT_HASH_SEED;
    for (let index = 0; index < input.length; index += 1) {
        hash ^= input.charCodeAt(index);
        hash = Math.imul(hash, 16777619);
    }

    return (hash >>> 0).toString(16).padStart(8, '0');
}

function hashSnapshotNode(
    relativePath: string,
    files: LocalLibrarySnapshotFile[],
    children: LocalLibrarySnapshotNode[]
): string {
    const normalizedFiles = files
        .map(file => `${file.kind}:${file.relativePath}:${file.size}:${file.lastModified}`)
        .sort()
        .join('|');
    const normalizedChildren = children
        .map(child => `${child.relativePath}:${child.hash}`)
        .sort()
        .join('|');

    return hashString(`${relativePath}__${normalizedFiles}__${normalizedChildren}`);
}

function getDurationFromParsedMetadata(durationSeconds?: number): number {
    if (typeof durationSeconds !== 'number' || !isFinite(durationSeconds) || durationSeconds <= 0) {
        return 0;
    }

    return Math.round(durationSeconds * 1000);
}

async function mapWithConcurrency<T, R>(
    items: T[],
    concurrency: number,
    mapper: (item: T, index: number) => Promise<R>
): Promise<R[]> {
    if (items.length === 0) {
        return [];
    }

    const results = new Array<R>(items.length);
    let nextIndex = 0;

    const worker = async () => {
        while (true) {
            const currentIndex = nextIndex++;
            if (currentIndex >= items.length) {
                return;
            }

            results[currentIndex] = await mapper(items[currentIndex], currentIndex);
        }
    };

    const workerCount = Math.min(concurrency, items.length);
    await Promise.all(Array.from({ length: workerCount }, () => worker()));
    return results;
}

async function extractEmbeddedMetadata(file: File, includeCover = false): Promise<EmbeddedMetadata> {
    const parsed = await parseEmbeddedMetadataAsync(file, includeCover);
    if (!parsed) {
        throw new Error('Metadata worker returned null');
    }
    return parsed;
}

async function extractSafHandleEmbeddedMetadata(
    fileHandle: AndroidSafFileHandle,
    includeCover = false,
): Promise<{ metadata: EmbeddedMetadata; statSize: number; statLastModified: number; mimeType: string; fileName: string }> {
    const stat = fileHandle.getStatMetadata();
    const nativeMeta = await fileHandle.extractNativeMetadata({
        includeCover,
        maxCoverDimension: 512,
    });

    let preparedNativeCover: PreparedLocalCoverBlob | undefined;
    if (includeCover && nativeMeta?.cover) {
        try {
            if (nativeMeta.coverAssetId && /^sha256:[a-f0-9]{64}$/i.test(nativeMeta.coverAssetId)) {
                stageLocalCoverAsset(nativeMeta.coverAssetId, nativeMeta.cover);
                preparedNativeCover = { assetId: nativeMeta.coverAssetId, blob: nativeMeta.cover };
            } else {
                preparedNativeCover = (await prepareLocalCoverBlob(nativeMeta.cover)) ?? undefined;
            }
        } catch (err) {
            console.warn(`[LocalMusic] Failed to prepare native cover thumbnail for ${stat.name}:`, err);
        }
    } else if (includeCover && nativeMeta?.coverAssetId && /^sha256:[a-f0-9]{64}$/i.test(nativeMeta.coverAssetId)) {
        // Disk cache hit in context.getFilesDir()/folia_media_cache/: 256x256 and 1024x1024 WebP
        // mipmaps already exist on disk and are served directly via /__folia_cover/{assetId}.
        preparedNativeCover = {
            assetId: nativeMeta.coverAssetId,
            blob: new Blob([], { type: 'image/webp' }),
        };
    }

    // When native MediaMetadataRetriever succeeded, it already inspected the embedded picture;
    // do not read a 1.5 MB cover slice into the JS worker for coverless tracks.
    const nativeConfirmedNoCover = Boolean(
        includeCover
        && nativeMeta
        && (nativeMeta.hasEmbeddedCover === false || !nativeMeta.cover)
    );
    const needWorkerCover = includeCover && !preparedNativeCover && !nativeConfirmedNoCover;
    const nativeMetadataComplete = Boolean(
        nativeMeta
        && nativeMeta.durationMs
        && nativeMeta.durationMs > 0
        && (!includeCover || preparedNativeCover || nativeMeta.hasEmbeddedCover === false)
    );
    let workerMeta: EmbeddedMetadata = {};
    if (!nativeMetadataComplete) {
        try {
            const headerFile = await fileHandle.getMetadataFile({ includeCover: needWorkerCover });
            workerMeta = await extractEmbeddedMetadata(headerFile, needWorkerCover);
        } catch (workerErr) {
            if (!nativeMeta) {
                throw workerErr;
            }
        }
    }

    const durationMs = workerMeta.duration
        || (nativeMeta?.durationMs && nativeMeta.durationMs > 0 ? Math.round(nativeMeta.durationMs) : undefined);
    const resolvedCover = preparedNativeCover?.blob ?? workerMeta.cover;
    const resolvedCoverAssetId = preparedNativeCover?.assetId ?? workerMeta.coverAssetId;

    if (resolvedCoverAssetId && (nativeMeta?.vibrantColors?.length || nativeMeta?.representativeColors?.length)) {
        const dualTheme = nativeMeta.vibrantColors?.length
            ? buildBuiltinDualTheme({ coverColors: nativeMeta.vibrantColors })
            : undefined;
        stageCachedCoverPalette(resolvedCoverAssetId, {
            vibrantColors: nativeMeta.vibrantColors,
            representativeColors: nativeMeta.representativeColors,
            dualTheme,
        });
        void writeCachedCoverPalette(resolvedCoverAssetId, {
            vibrantColors: nativeMeta.vibrantColors,
            representativeColors: nativeMeta.representativeColors,
            dualTheme,
        });
    }

    const merged: EmbeddedMetadata = {
        ...workerMeta,
        title: workerMeta.title || nativeMeta?.title,
        artist: workerMeta.artist || nativeMeta?.artist,
        artists: workerMeta.artists?.length
            ? workerMeta.artists
            : (nativeMeta?.artist ? [nativeMeta.artist] : undefined),
        albumArtist: workerMeta.albumArtist || nativeMeta?.albumArtist,
        album: workerMeta.album || nativeMeta?.album,
        year: workerMeta.year ?? nativeMeta?.year,
        genre: workerMeta.genre || nativeMeta?.genre,
        codec: workerMeta.codec || nativeMeta?.codec,
        duration: durationMs,
        bitrate: workerMeta.bitrate || nativeMeta?.bitrate,
        trackNumber: workerMeta.trackNumber ?? nativeMeta?.trackNumber,
        discNumber: workerMeta.discNumber ?? nativeMeta?.discNumber,
        lyrics: workerMeta.lyrics || nativeMeta?.lyrics,
        translationLyrics: workerMeta.translationLyrics || nativeMeta?.translationLyrics,
        cover: resolvedCover,
        coverAssetId: resolvedCoverAssetId,
        hasEmbeddedCover: includeCover ? Boolean(resolvedCover && resolvedCoverAssetId) : undefined,
    };

    if (merged.lyrics) {
        void LyricParserFactory.parse({
            type: 'embedded',
            textContent: merged.lyrics,
            translationContent: merged.translationLyrics,
        }).catch(() => undefined);
    }

    return {
        metadata: merged,
        statSize: stat.size,
        statLastModified: stat.lastModified,
        mimeType: stat.type,
        fileName: stat.name,
    };
}

async function buildSnapshotTree(
    handle: FileSystemDirectoryHandle,
    currentPath: string,
    rootFolderName: string,
    inheritedIgnoreMatchers: readonly FoliaIgnoreMatcher[],
    filesByPath = new Map<string, SnapshotTraversalFile>(),
    ignoredFolderPaths: ReadonlySet<string> = new Set(),
): Promise<SnapshotTraversalResult> {
    const files: LocalLibrarySnapshotFile[] = [];
    const children: LocalLibrarySnapshotNode[] = [];
    let relevantFileCount = 0;

    const directoryRelativePath = currentPath === rootFolderName
        ? ''
        : currentPath.slice(rootFolderName.length + 1);
    const childEntries: Array<FileSystemHandle> = [];

    try {
        // @ts-ignore
        for await (const entry of handle.values()) {
            childEntries.push(entry);
        }
    } catch (error) {
        console.warn(`[LocalMusic][Import] Skip unreadable directory "${currentPath}":`, error);

        return {
            tree: {
                name: handle.name,
                relativePath: currentPath,
                hash: hashSnapshotNode(currentPath, [], []),
                files: [],
                children: []
            },
            relevantFileCount: 0,
            filesByPath,
        };
    }

    childEntries.sort((a, b) => a.name.localeCompare(b.name));
    const ignoreHandle = childEntries.find(entry => entry.kind === 'file' && entry.name === '.foliaignore');
    const localIgnoreMatcher = await loadFoliaIgnoreMatcher(
        ignoreHandle as FileSystemFileHandle | undefined,
        directoryRelativePath,
        handle.name,
    );
    const ignoreMatchers = localIgnoreMatcher.ruleCount > 0
        ? [...inheritedIgnoreMatchers, localIgnoreMatcher]
        : inheritedIgnoreMatchers;

    for (const entry of childEntries) {
        if (entry.name === '.foliaignore') {
            continue;
        }

        const entryPath = `${currentPath}/${entry.name}`;
        if (entry.kind === 'directory' && ignoredFolderPaths.has(entryPath)) {
            children.push({ name: entry.name, relativePath: entryPath, ignored: true, hash: '', files: [], children: [] });
            continue;
        }
        const importRelativePath = entryPath.startsWith(`${rootFolderName}/`)
            ? entryPath.slice(rootFolderName.length + 1)
            : entryPath;
        if (isIgnoredByFoliaMatchers(ignoreMatchers, importRelativePath, entry.kind === 'directory')) {
            continue;
        }

        if (entry.kind === 'directory') {
            const childPath = entryPath;

            try {
                const childResult = await buildSnapshotTree(
                    entry as FileSystemDirectoryHandle,
                    childPath,
                    rootFolderName,
                    ignoreMatchers,
                    filesByPath,
                    ignoredFolderPaths,
                );
                children.push(childResult.tree);
                relevantFileCount += childResult.relevantFileCount;
            } catch (error) {
                console.warn(`[LocalMusic][Import] Skip failed child directory "${childPath}":`, error);
            }

            continue;
        }

        const kind = getSnapshotFileKind(entry.name);
        if (kind === 'other') {
            continue;
        }

        const fileHandle = entry as FileSystemFileHandle;

        try {
            const file = isAndroidSafFileHandle(fileHandle)
                ? createLightweightStatFile(fileHandle)
                : await fileHandle.getFile();
            const relativePath = `${currentPath}/${file.name}`;
            const signature = buildFileSignature(relativePath, file.size, file.lastModified);

            files.push({
                name: file.name,
                relativePath,
                kind,
                size: file.size,
                lastModified: file.lastModified,
                signature
            });
            filesByPath.set(relativePath, { handle: fileHandle, file });
            relevantFileCount += 1;
        } catch (error) {
            console.warn(`[LocalMusic][Import] Skip unreadable file "${currentPath}/${entry.name}":`, error);
        }
    }

    const tree: LocalLibrarySnapshotNode = {
        name: handle.name,
        relativePath: currentPath,
        hash: hashSnapshotNode(currentPath, files, children),
        files,
        children
    };

    return { tree, relevantFileCount, filesByPath };
}

async function loadFoliaIgnoreMatcher(
    ignoreHandle: FileSystemFileHandle | undefined,
    baseDirectory: string,
    directoryName: string,
): Promise<FoliaIgnoreMatcher> {
    if (!ignoreHandle) {
        return createFoliaIgnoreMatcher('', baseDirectory);
    }

    try {
        const ignoreFile = await ignoreHandle.getFile();
        const matcher = createFoliaIgnoreMatcher(await ignoreFile.text(), baseDirectory);
        console.log(`[LocalMusic][Import] Loaded ${matcher.ruleCount} .foliaignore rules from "${directoryName}".`);
        return matcher;
    } catch (error) {
        console.warn(`[LocalMusic][Import] Failed to read .foliaignore from "${directoryName}":`, error);
        return createFoliaIgnoreMatcher('', baseDirectory);
    }
}

function flattenSnapshotFiles(node: LocalLibrarySnapshotNode, target = new Map<string, LocalLibrarySnapshotFile>()) {
    node.files.forEach(file => {
        target.set(file.relativePath, file);
    });
    node.children.forEach(child => flattenSnapshotFiles(child, target));
    return target;
}

async function collectImportDiffPlan(
    rootFolderName: string,
    dirHandle: FileSystemDirectoryHandle,
    existingSongs: LocalSong[],
    previousSnapshot: LocalLibrarySnapshot | null,
    lyricFormatOrder: LocalLyricFileFormat[]
): Promise<ImportDiffPlan> {
    if (isAndroidSafDirectoryHandle(dirHandle)) {
        invalidateAndroidSafTreeCache(dirHandle.treeUri);
    }
    const ignoredFolderPaths = previousSnapshot?.ignoredFolderPaths || [];
    const traversalResult = await buildSnapshotTree(dirHandle, rootFolderName, rootFolderName, [], new Map(), new Set(ignoredFolderPaths));
    const snapshot: LocalLibrarySnapshot = {
        rootFolderName,
        scannedAt: Date.now(),
        ignoredFolderPaths,
        lyricFormatOrder,
        tree: traversalResult.tree
    };

    const currentFiles = flattenSnapshotFiles(snapshot.tree);
    const previousFiles = previousSnapshot ? flattenSnapshotFiles(previousSnapshot.tree) : new Map<string, LocalLibrarySnapshotFile>();
    const existingSongsByPath = new Map<string, LocalSong>();
    const duplicateExistingSongs: LocalSong[] = [];
    for (const song of existingSongs) {
        const prev = existingSongsByPath.get(song.filePath);
        if (!prev) {
            existingSongsByPath.set(song.filePath, song);
            continue;
        }
        const prevHydrated = prev.embeddedMetadataVersion === EMBEDDED_METADATA_VERSION && !prev.localCoverNeedsAssetMigration;
        const currHydrated = song.embeddedMetadataVersion === EMBEDDED_METADATA_VERSION && !song.localCoverNeedsAssetMigration;
        if (currHydrated && !prevHydrated) {
            duplicateExistingSongs.push(prev);
            existingSongsByPath.set(song.filePath, song);
        } else {
            duplicateExistingSongs.push(song);
        }
    }
    const currentAudioPaths = new Set<string>();
    const changedAudioPaths = new Set<string>();
    const changedLyricBasePaths = new Set<string>();
    // Subset of changedLyricBasePaths whose files changed on disk, as opposed to only being
    // re-ranked by a format order change. Only these may replace lyrics the user uploaded.
    const lyricFileChangedBasePaths = new Set<string>();
    const changedCoverFolders = new Set<string>();
    // Built in the same pass over the current files, so mapping a changed sidecar or folder cover
    // back to its tracks is a lookup instead of a scan of the whole library per path.
    const audioPathsByBasePath = new Map<string, string[]>();
    const audioPathsByFolder = new Map<string, string[]>();
    const appendToGroup = (groups: Map<string, string[]>, key: string, value: string) => {
        const group = groups.get(key);
        if (group) {
            group.push(value);
        } else {
            groups.set(key, [value]);
        }
    };
    const lyricCandidates = new Map<string, { file: File; priority: number; format?: ExplicitFileTimedLyricFormat; }>();
    const translationLyricCandidates = new Map<string, { file: File; priority: number; }>();
    const coverCandidates = new Map<string, { file: File; priority: number; }>();

    currentFiles.forEach((file) => {
        const previousFile = previousFiles.get(file.relativePath);
        const hasChanged = !previousFile || previousFile.signature !== file.signature || previousFile.kind !== file.kind;

        if (file.kind === 'audio') {
            currentAudioPaths.add(file.relativePath);
            appendToGroup(audioPathsByBasePath, getAudioBasePath(file.relativePath), file.relativePath);
            appendToGroup(audioPathsByFolder, getParentRelativePath(file.relativePath), file.relativePath);
            if (hasChanged || !existingSongsByPath.has(file.relativePath)) {
                changedAudioPaths.add(file.relativePath);
            }
            return;
        }

        if (hasChanged && (file.kind === 'lyric' || file.kind === 'translationLyric')) {
            const basePath = getSidecarLyricBasePath(file.relativePath, file.kind);
            changedLyricBasePaths.add(basePath);
            lyricFileChangedBasePaths.add(basePath);
        }

        if (file.kind === 'cover' && hasChanged) {
            changedCoverFolders.add(getParentRelativePath(file.relativePath));
        }
    });

    // Snapshots written before the order became configurable were scanned with the default order.
    const previousLyricFormatOrder = normalizeLocalLyricFormatOrder(previousSnapshot?.lyricFormatOrder);
    if (previousSnapshot && !isSameLocalLyricFormatOrder(previousLyricFormatOrder, lyricFormatOrder)) {
        collectLyricBasePathsAffectedByFormatOrder(Array.from(currentFiles.values()), previousLyricFormatOrder, lyricFormatOrder)
            .forEach(basePath => changedLyricBasePaths.add(basePath));
    }

    const previousAudioPaths = Array.from(previousFiles.values())
        .filter(file => file.kind === 'audio')
        .map(file => file.relativePath);

    previousAudioPaths.forEach((relativePath) => {
        if (!currentAudioPaths.has(relativePath)) {
            const removedSong = existingSongsByPath.get(relativePath);
            if (removedSong) {
                existingSongsByPath.delete(relativePath);
            }
        }
    });

    // "Track.mp3" and "Track.flac" share one sidecar, so every track with that base path is rebuilt.
    changedLyricBasePaths.forEach(basePath => {
        audioPathsByBasePath.get(basePath)?.forEach(audioPath => changedAudioPaths.add(audioPath));
    });

    previousFiles.forEach((file) => {
        if (file.kind === 'cover' && !currentFiles.has(file.relativePath)) {
            changedCoverFolders.add(getParentRelativePath(file.relativePath));
        }
    });

    changedCoverFolders.forEach(folderPath => {
        audioPathsByFolder.get(folderPath)?.forEach(audioPath => changedAudioPaths.add(audioPath));
    });

    const changedEntries: FileEntryForImport[] = [];
    const reusedSongs: LocalSong[] = [];
    const duplicateSongIds = new Set(duplicateExistingSongs.map(song => song.id));
    const removedSongs = [
        ...duplicateExistingSongs,
        ...existingSongs.filter(song => !duplicateSongIds.has(song.id) && !currentAudioPaths.has(song.filePath)),
    ];
    const allRelevantFiles = Array.from(currentFiles.values()).sort((a, b) => a.relativePath.localeCompare(b.relativePath));

    for (const snapshotFile of allRelevantFiles) {
        const traversedFile = traversalResult.filesByPath.get(snapshotFile.relativePath);
        if (!traversedFile) {
            console.warn(`[LocalMusic][Import] Missing traversed file handle for "${snapshotFile.relativePath}".`);
            continue;
        }

        const pathSegments = snapshotFile.relativePath.split('/');
        const fileName = pathSegments[pathSegments.length - 1];
        const folderName = pathSegments.slice(0, -1).join('/');

        if (snapshotFile.kind === 'lyric' || snapshotFile.kind === 'translationLyric') {
            const baseName = getSidecarLyricBasePath(snapshotFile.relativePath, snapshotFile.kind);
            const priority = getLocalLyricFilePriority(snapshotFile.name, lyricFormatOrder);
            const format = resolveExplicitFileTimedLyricFormat(snapshotFile.name);

            if (snapshotFile.kind === 'translationLyric') {
                const existingTranslationLyric = translationLyricCandidates.get(baseName);
                if (!existingTranslationLyric || priority < existingTranslationLyric.priority) {
                    translationLyricCandidates.set(baseName, { file: traversedFile.file, priority });
                }
            } else {
                const existingLyric = lyricCandidates.get(baseName);
                if (!existingLyric || priority < existingLyric.priority) {
                    lyricCandidates.set(baseName, { file: traversedFile.file, priority, format });
                }
            }
            continue;
        }

        if (snapshotFile.kind === 'cover') {
            const folderKey = getParentRelativePath(snapshotFile.relativePath);
            const priority = getFolderCoverPriority(snapshotFile.name);
            const existingCover = coverCandidates.get(folderKey);

            if (!existingCover || priority < existingCover.priority) {
                coverCandidates.set(folderKey, { file: traversedFile.file, priority });
            }
            continue;
        }

        if (snapshotFile.kind !== 'audio') {
            continue;
        }

        const existingSong = existingSongsByPath.get(snapshotFile.relativePath);

        if (
            changedAudioPaths.has(snapshotFile.relativePath)
            || !existingSong
            || existingSong.embeddedMetadataVersion !== EMBEDDED_METADATA_VERSION
            || existingSong.localCoverNeedsAssetMigration
        ) {
            changedEntries.push({
                handle: traversedFile.handle,
                file: traversedFile.file,
                folderName,
                relativePath: snapshotFile.relativePath,
                sidecarLyricFilesChanged: lyricFileChangedBasePaths.has(getAudioBasePath(snapshotFile.relativePath)),
            });
            continue;
        }

        fileHandleMap.set(existingSong.id, traversedFile.handle);
        existingSong.fileHandle = traversedFile.handle;
        if (isAndroidSafFileHandle(traversedFile.handle)) {
            existingSong.safContentUri = traversedFile.handle.contentUri;
            existingSong.safTreeUri = traversedFile.handle.treeUri;
            existingSong.safDocumentId = traversedFile.handle.documentId;
        }
        existingSong.fileSize = snapshotFile.size;
        existingSong.fileLastModified = snapshotFile.lastModified;
        existingSong.fileSignature = snapshotFile.signature;
        reusedSongs.push(existingSong);
    }

    const discoveredVideos: VideoSnapshotFileDescriptor[] = [];
    currentFiles.forEach((file) => {
        if (file.kind !== 'video') return;
        const traversalEntry = traversalResult.filesByPath.get(file.relativePath);
        discoveredVideos.push({
            name: file.name,
            relativePath: file.relativePath,
            folderName: getParentRelativePath(file.relativePath) || rootFolderName,
            size: file.size,
            lastModified: file.lastModified,
            mimeType: traversalEntry?.file.type,
            handle: traversalEntry?.handle,
        });
    });
    void reconcileVideosForRootFolder(rootFolderName, discoveredVideos).catch(err => {
        console.warn('[LocalMusic][Import] Failed to reconcile album videos in music folder:', err);
    });

    return {
        changedEntries,
        reusedSongs,
        removedSongs,
        totalAudioFiles: currentAudioPaths.size,
        relevantFileCount: traversalResult.relevantFileCount,
        lrcMap: new Map(Array.from(lyricCandidates.entries()).map(([baseName, value]) => [baseName, { file: value.file, format: value.format }])),
        tlrcMap: new Map(Array.from(translationLyricCandidates.entries()).map(([baseName, value]) => [baseName, value.file])),
        coverMap: new Map(Array.from(coverCandidates.entries()).map(([folderKey, value]) => [folderKey, value.file])),
        snapshot
    };
}

async function buildImportedSong(
    entry: FileEntryForImport,
    lrcMap: Map<string, LocalLyricFileCandidate>,
    tlrcMap: Map<string, File>,
    coverMap: Map<string, File>,
    coverBlobCache: Map<string, Promise<PreparedLocalCoverBlob | undefined>>,
    includeEmbeddedMetadata = true,
    existingSong?: LocalSong
): Promise<{ song: LocalSong | null; metrics: ImportPreparationMetrics; }> {
    const fileHandle = entry.handle;
    const file = entry.file;
    const getFileMs = 0;

    if (!isAudioFile(file)) {
        return {
            song: null,
            metrics: {
                getFileMs,
                lyricReadMs: 0,
                coverReadMs: 0,
                parseMetadataMs: 0,
                durationFallbackMs: 0,
                usedDurationFallback: false
            }
        };
    }

    const metadata = extractMetadataFromFilename(file.name);
    const baseName = getAudioBasePath(entry.relativePath);

    let localLyricsContent: string | undefined;
    let localLyricsFormat: ExplicitFileTimedLyricFormat | undefined;
    let localTranslationLyricsContent: string | undefined;
    const lyricReadStartedAt = performance.now();
    // Uploaded lyrics survive rescans (including a format order change) until a sidecar lyric of
    // this track changes on disk: whichever explicit action is newer wins.
    const keepUploadedLyrics = existingSong?.localLyricsOrigin === 'upload' && !entry.sidecarLyricFilesChanged;
    const keepUploadedTranslation = existingSong?.localTranslationLyricsOrigin === 'upload' && !entry.sidecarLyricFilesChanged;

    if (keepUploadedLyrics) {
        localLyricsContent = existingSong?.localLyricsContent;
        localLyricsFormat = existingSong?.localLyricsFormat;
    } else if (lrcMap.has(baseName)) {
        try {
            const lyricCandidate = lrcMap.get(baseName)!;
            const loadedLyricFile = await ensureLoadedSafFile(lyricCandidate.file);
            localLyricsContent = await readLyricFile(loadedLyricFile);
            localLyricsFormat = lyricCandidate.format;
        } catch (e) {
            console.error(`[LocalMusic] Failed to read local lyric for ${file.name}`, e);
        }
    }

    if (keepUploadedTranslation) {
        localTranslationLyricsContent = existingSong?.localTranslationLyricsContent;
    } else if (tlrcMap.has(baseName)) {
        try {
            const loadedTranslationFile = await ensureLoadedSafFile(tlrcMap.get(baseName)!);
            localTranslationLyricsContent = await readLyricFile(loadedTranslationFile);
        } catch (e) {
            console.error(`[LocalMusic] Failed to read local translation lyric for ${file.name}`, e);
        }
    }
    const lyricReadMs = performance.now() - lyricReadStartedAt;

    let folderCover: PreparedLocalCoverBlob | undefined;
    const coverReadStartedAt = performance.now();
    if (coverMap.has(entry.folderName)) {
        if (!coverBlobCache.has(entry.folderName)) {
            coverBlobCache.set(entry.folderName, (async () => {
                try {
                    const loadedCoverFile = await ensureLoadedSafFile(coverMap.get(entry.folderName)!);
                    return (await prepareLocalCoverBlob(loadedCoverFile)) || undefined;
                } catch (error) {
                    console.warn(`[LocalMusic] Failed to read folder cover for ${entry.folderName}:`, error);
                    return undefined;
                }
            })());
        }
        folderCover = await coverBlobCache.get(entry.folderName)!;
    }
    const coverReadMs = performance.now() - coverReadStartedAt;

    let embeddedMetadata: EmbeddedMetadata = {};
    let parseMetadataMs = 0;
    if (includeEmbeddedMetadata) {
        const parseMetadataStartedAt = performance.now();

        try {
            embeddedMetadata = await extractEmbeddedMetadata(file, false);
        } catch (e) {
            console.warn(`[LocalMusic] Failed to parse metadata for ${file.name}:`, e);
        }
        parseMetadataMs = performance.now() - parseMetadataStartedAt;
    }

    let durationFallbackMs = 0;
    let usedDurationFallback = false;
    let duration = embeddedMetadata.duration || 0;
    if (includeEmbeddedMetadata && !duration) {
        usedDurationFallback = true;
        const durationFallbackStartedAt = performance.now();
        duration = await getAudioDuration(file);
        durationFallbackMs = performance.now() - durationFallbackStartedAt;
    }

    const songId = existingSong?.id || generateId();
    const nextFileSignature = buildFileSignature(entry.relativePath, file.size, file.lastModified);
    const preserveHydratedAudioMetadata = Boolean(
        !includeEmbeddedMetadata
        && existingSong
        && existingSong.fileSignature === nextFileSignature
        && existingSong.embeddedMetadataVersion === EMBEDDED_METADATA_VERSION
        && !existingSong.localCoverNeedsAssetMigration
    );
    const importedMetadata = preserveHydratedAudioMetadata && existingSong?.importedMetadata
        ? existingSong.importedMetadata
        : buildImportedMetadataSnapshot({
            fileName: file.name,
            embeddedTitle: embeddedMetadata.title,
            fallbackTitle: metadata.title,
            embeddedArtist: embeddedMetadata.artist,
            embeddedArtists: embeddedMetadata.artists,
            fallbackArtist: metadata.artist,
            embeddedAlbum: embeddedMetadata.album,
            embeddedAlbumArtist: embeddedMetadata.albumArtist,
            embeddedYear: embeddedMetadata.year,
            embeddedGenre: embeddedMetadata.genre,
            embeddedCodec: embeddedMetadata.codec,
        });
    const titleOrigin = existingSong?.titleOrigin || 'import';
    const safFields = isAndroidSafFileHandle(fileHandle)
        ? {
            safContentUri: fileHandle.contentUri,
            safTreeUri: fileHandle.treeUri,
            safDocumentId: fileHandle.documentId,
        }
        : (preserveHydratedAudioMetadata
            ? {
                safContentUri: existingSong?.safContentUri,
                safTreeUri: existingSong?.safTreeUri,
                safDocumentId: existingSong?.safDocumentId,
            }
            : {});
    const localSong: LocalSong = {
        ...existingSong,
        ...safFields,
        id: songId,
        fileName: file.name,
        filePath: entry.relativePath,
        duration: preserveHydratedAudioMetadata ? (existingSong?.duration || 0) : duration,
        fileSize: file.size,
        fileLastModified: file.lastModified,
        fileSignature: nextFileSignature,
        mimeType: file.type,
        codec: preserveHydratedAudioMetadata ? existingSong?.codec : embeddedMetadata.codec,
        bitrate: preserveHydratedAudioMetadata ? (existingSong?.bitrate || 0) : (embeddedMetadata.bitrate || 0),
        addedAt: existingSong?.addedAt || Date.now(),
        title: titleOrigin === 'import' ? importedMetadata.title : existingSong?.title || importedMetadata.title,
        titleOrigin,
        importedMetadata,
        onlineMetadata: existingSong?.onlineMetadata,
        albumArtist: preserveHydratedAudioMetadata ? existingSong?.albumArtist : embeddedMetadata.albumArtist,
        trackNumber: preserveHydratedAudioMetadata ? existingSong?.trackNumber : embeddedMetadata.trackNumber,
        discNumber: preserveHydratedAudioMetadata ? existingSong?.discNumber : embeddedMetadata.discNumber,
        year: preserveHydratedAudioMetadata ? existingSong?.year : embeddedMetadata.year,
        genre: preserveHydratedAudioMetadata ? existingSong?.genre : embeddedMetadata.genre,
        embeddedMetadataVersion: preserveHydratedAudioMetadata ? existingSong?.embeddedMetadataVersion : undefined,
        hydrationFailedSignature: preserveHydratedAudioMetadata ? existingSong?.hydrationFailedSignature : undefined,
        localCoverAssetId: folderCover
            ? folderCover.assetId
            : (preserveHydratedAudioMetadata && existingSong?.localCoverSource === 'embedded'
                ? existingSong.localCoverAssetId
                : undefined),
        localCoverSource: folderCover
            ? 'folder'
            : (preserveHydratedAudioMetadata && existingSong?.localCoverSource === 'embedded'
                ? 'embedded'
                : undefined),
        localCoverNeedsAssetMigration: folderCover && !folderCover.assetId
            ? true
            : (preserveHydratedAudioMetadata ? existingSong?.localCoverNeedsAssetMigration : undefined),
        hasNoEmbeddedCover: folderCover
            ? false
            : (preserveHydratedAudioMetadata ? existingSong?.hasNoEmbeddedCover : undefined),
        hasManualLyricSelection: existingSong?.hasManualLyricSelection ?? false,
        folderName: entry.folderName,
        hasLocalLyrics: !!localLyricsContent,
        localLyricsContent,
        localLyricsFormat: localLyricsContent ? localLyricsFormat : undefined,
        localLyricsOrigin: localLyricsContent ? (keepUploadedLyrics ? 'upload' : 'sidecar') : undefined,
        hasLocalTranslationLyrics: !!localTranslationLyricsContent,
        localTranslationLyricsContent,
        localTranslationLyricsOrigin: localTranslationLyricsContent ? (keepUploadedTranslation ? 'upload' : 'sidecar') : undefined,
        hasEmbeddedLyrics: preserveHydratedAudioMetadata ? Boolean(existingSong?.hasEmbeddedLyrics) : !!embeddedMetadata.lyrics,
        embeddedLyricsContent: preserveHydratedAudioMetadata ? existingSong?.embeddedLyricsContent : embeddedMetadata.lyrics,
        hasEmbeddedTranslationLyrics: preserveHydratedAudioMetadata ? Boolean(existingSong?.hasEmbeddedTranslationLyrics) : !!embeddedMetadata.translationLyrics,
        embeddedTranslationLyricsContent: preserveHydratedAudioMetadata ? existingSong?.embeddedTranslationLyricsContent : embeddedMetadata.translationLyrics,
        replayGain: preserveHydratedAudioMetadata ? existingSong?.replayGain : embeddedMetadata.replayGain,
        replayGainTrackGain: preserveHydratedAudioMetadata ? existingSong?.replayGainTrackGain : embeddedMetadata.replayGainTrackGain,
        replayGainTrackPeak: preserveHydratedAudioMetadata ? existingSong?.replayGainTrackPeak : embeddedMetadata.replayGainTrackPeak,
        replayGainAlbumGain: preserveHydratedAudioMetadata ? existingSong?.replayGainAlbumGain : embeddedMetadata.replayGainAlbumGain,
        replayGainAlbumPeak: preserveHydratedAudioMetadata ? existingSong?.replayGainAlbumPeak : embeddedMetadata.replayGainAlbumPeak,
        matchedLyrics: existingSong?.matchedLyrics,
        matchedIsPureMusic: existingSong?.matchedIsPureMusic,
        markedPureMusic: existingSong?.markedPureMusic,
        matchedLyricsSongId: existingSong?.matchedLyricsSongId,
        matchedLyricsSource: existingSong?.matchedLyricsSource,
        matchedLyricsProviderPlatform: existingSong?.matchedLyricsProviderPlatform,
        noAutoMatch: existingSong?.noAutoMatch,
        lyricsSource: existingSong?.lyricsSource,
        useOnlineCover: existingSong?.useOnlineCover,
    };

    fileHandleMap.set(songId, fileHandle);
    localSong.fileHandle = fileHandle;

    return {
        song: localSong,
        metrics: {
            getFileMs,
            lyricReadMs,
            coverReadMs,
            parseMetadataMs,
            durationFallbackMs,
            usedDurationFallback
        }
    };
}

async function hydrateSongMetadata(song: LocalSong): Promise<{ song: LocalSong; failed: boolean }> {
    let fileHandle = fileHandleMap.get(song.id) || song.fileHandle;
    if (!fileHandle) {
        fileHandle = (await recoverFileHandleFromPersistedDirectory(song)) ?? undefined;
    }
    if (!fileHandle) {
        return { song, failed: true };
    }

    try {
        const includeCover = song.localCoverSource !== 'folder';
        let embeddedMetadata: EmbeddedMetadata;
        let coverHydrationFailed = false;
        let fileSize = song.fileSize;
        let fileLastModified = song.fileLastModified;
        let mimeType = song.mimeType;
        let fileName = song.fileName;

        if (isAndroidSafFileHandle(fileHandle)) {
            try {
                const extracted = await extractSafHandleEmbeddedMetadata(fileHandle, includeCover);
                embeddedMetadata = extracted.metadata;
                fileSize = extracted.statSize || fileSize;
                fileLastModified = extracted.statLastModified || fileLastModified;
                mimeType = extracted.mimeType || mimeType;
                fileName = extracted.fileName || fileName;
            } catch (coverError) {
                if (!includeCover) throw coverError;
                coverHydrationFailed = true;
                console.warn(`[LocalMusic][Import] Cover-aware SAF metadata parsing failed for ${song.fileName}; retrying without covers.`, coverError);
                const extracted = await extractSafHandleEmbeddedMetadata(fileHandle, false);
                embeddedMetadata = extracted.metadata;
                fileSize = extracted.statSize || fileSize;
                fileLastModified = extracted.statLastModified || fileLastModified;
                mimeType = extracted.mimeType || mimeType;
                fileName = extracted.fileName || fileName;
            }
        } else {
            const file = await fileHandle.getFile();
            fileSize = file.size;
            fileLastModified = file.lastModified;
            mimeType = file.type;
            fileName = file.name;
            try {
                embeddedMetadata = await extractEmbeddedMetadata(file, includeCover);
            } catch (coverError) {
                if (!includeCover) throw coverError;
                coverHydrationFailed = true;
                console.warn(`[LocalMusic][Import] Cover-aware metadata parsing failed for ${song.fileName}; retrying without covers.`, coverError);
                embeddedMetadata = await extractEmbeddedMetadata(file, false);
            }
        }

        song.duration = embeddedMetadata.duration || song.duration || 0;
        song.fileSize = fileSize;
        // Kept in step with fileSize: buildLocalSourceRevision reads both, so refreshing only one
        // makes every cached playback representation look stale and re-transcode on each play.
        song.fileLastModified = fileLastModified;
        if (isAndroidSafFileHandle(fileHandle)) {
            song.safContentUri = fileHandle.contentUri;
            song.safTreeUri = fileHandle.treeUri;
            song.safDocumentId = fileHandle.documentId;
        }
        song.mimeType = mimeType;
        song.codec = embeddedMetadata.codec || song.codec;
        song.bitrate = embeddedMetadata.bitrate || song.bitrate || 0;
        const filenameMetadata = extractMetadataFromFilename(fileName);
        song.importedMetadata = buildImportedMetadataSnapshot({
            fileName,
            embeddedTitle: embeddedMetadata.title,
            fallbackTitle: filenameMetadata.title,
            embeddedArtist: embeddedMetadata.artist,
            embeddedArtists: embeddedMetadata.artists,
            fallbackArtist: filenameMetadata.artist,
            embeddedAlbum: embeddedMetadata.album,
            embeddedAlbumArtist: embeddedMetadata.albumArtist,
            embeddedYear: embeddedMetadata.year,
            embeddedGenre: embeddedMetadata.genre,
            embeddedCodec: embeddedMetadata.codec,
        });
        if (song.titleOrigin === 'import') song.title = song.importedMetadata.title;
        song.albumArtist = embeddedMetadata.albumArtist;
        song.trackNumber = embeddedMetadata.trackNumber;
        song.discNumber = embeddedMetadata.discNumber;
        song.year = embeddedMetadata.year;
        song.genre = embeddedMetadata.genre;
        song.embeddedMetadataVersion = EMBEDDED_METADATA_VERSION;
        song.hydrationFailedSignature = undefined;
        song.hasEmbeddedLyrics = !!embeddedMetadata.lyrics;
        song.embeddedLyricsContent = embeddedMetadata.lyrics;
        song.hasEmbeddedTranslationLyrics = !!embeddedMetadata.translationLyrics;
        song.embeddedTranslationLyricsContent = embeddedMetadata.translationLyrics;
        song.replayGain = embeddedMetadata.replayGain;
        song.replayGainTrackGain = embeddedMetadata.replayGainTrackGain;
        song.replayGainTrackPeak = embeddedMetadata.replayGainTrackPeak;
        song.replayGainAlbumGain = embeddedMetadata.replayGainAlbumGain;
        song.replayGainAlbumPeak = embeddedMetadata.replayGainAlbumPeak;
        if (includeCover) {
            if (embeddedMetadata.cover && embeddedMetadata.coverAssetId) {
                stageLocalCoverAsset(embeddedMetadata.coverAssetId, embeddedMetadata.cover);
                song.localCoverAssetId = embeddedMetadata.coverAssetId;
                song.localCoverSource = 'embedded';
                song.hasNoEmbeddedCover = false;
                song.localCoverNeedsAssetMigration = coverHydrationFailed ? true : undefined;
                songsWithoutEmbeddedCover.delete(song.id);
            } else if (!coverHydrationFailed) {
                song.localCoverAssetId = undefined;
                song.localCoverSource = undefined;
                song.hasNoEmbeddedCover = true;
                song.localCoverNeedsAssetMigration = undefined;
                songsWithoutEmbeddedCover.set(song.id, `${fileSize}:${fileLastModified}`);
            } else {
                song.localCoverNeedsAssetMigration = true;
            }
        }
        return { song, failed: false };
    } catch (error) {
        console.warn(`[LocalMusic][Import] Failed to hydrate metadata for ${song.fileName}:`, error);
        song.hydrationFailedSignature = song.fileSignature || `${song.filePath}::${song.fileSize}::${song.fileLastModified ?? 0}`;
        song.embeddedMetadataVersion = EMBEDDED_METADATA_VERSION;
        return { song, failed: true };
    }
}

const removedRootGenerations = new Map<string, number>();

interface HydrationScanSummaryContext {
    discoveredSongs: number;
    skippedSongs: number;
    initialFailedSongs: number;
    alreadyHydratedChangedSongs: number;
    startedGlobalEpoch: number;
    startedRootEpoch: number;
}

async function hydrateImportedSongsInBackground(
    rootFolderName: string,
    songs: LocalSong[],
    context?: Partial<HydrationScanSummaryContext>,
) {
    const normalizedRoot = rootFolderName.split('/')[0] || rootFolderName;
    const rootGeneration = removedRootGenerations.get(normalizedRoot);
    const startedGlobalEpoch = context?.startedGlobalEpoch ?? globalScanCancelEpoch;
    const startedRootEpoch = context?.startedRootEpoch ?? (cancelledScanRoots.get(normalizedRoot) || 0);
    const discoveredSongs = context?.discoveredSongs ?? songs.length;
    const skippedSongs = context?.skippedSongs ?? 0;
    const baseProcessedSongs = context?.alreadyHydratedChangedSongs ?? 0;
    let failedSongs = context?.initialFailedSongs ?? 0;

    if (songs.length === 0) {
        notifyLocalMusicScanProgress({
            active: false,
            folderName: rootFolderName,
            phase: 'completed',
            totalSongs: discoveredSongs,
            completedSongs: discoveredSongs,
            discoveredSongs,
            processedSongs: baseProcessedSongs,
            skippedSongs,
            failedSongs,
            cancelled: false,
        });
        return;
    }

    const hydrationStartedAt = performance.now();
    const pendingBatch: LocalSong[] = [];
    let savedCount = 0;
    let nextIndex = 0;
    let flushInFlight: Promise<void> | null = null;
    let wasCancelled = false;

    const isCancelled = () => (
        removedRootGenerations.get(normalizedRoot) !== rootGeneration
        || isLocalLibraryScanCancelled(normalizedRoot, startedGlobalEpoch, startedRootEpoch)
    );

    notifyLocalMusicScanProgress({
        active: true,
        folderName: rootFolderName,
        phase: 'hydrating',
        totalSongs: songs.length,
        completedSongs: 0,
        discoveredSongs,
        processedSongs: baseProcessedSongs,
        skippedSongs,
        failedSongs,
        cancelled: false,
    });

    const flushBatch = async (forceNotify = false) => {
        while (flushInFlight) {
            await flushInFlight;
        }
        if (pendingBatch.length === 0) {
            return;
        }

        const batch = pendingBatch.splice(0, pendingBatch.length);
        const currentFlush = (async () => {
            await runLocalFolderMutation(async () => {
                if (removedRootGenerations.get(normalizedRoot) !== rootGeneration) return;
                const ignoredPaths = (await getLocalLibrarySnapshot(rootFolderName))?.ignoredFolderPaths || [];
                const visibleBatch = batch.filter(song => !isLocalFolderIgnored(song.folderName || song.filePath, ignoredPaths));
                repairSwappedTitleArtistAndAlbumMetadata(visibleBatch, songs);
                if (visibleBatch.length > 0) await saveLocalSongs(visibleBatch);
            });
            savedCount += batch.length;
            if (forceNotify || savedCount % HYDRATION_REFRESH_EVERY === 0 || savedCount === songs.length) {
                notifyLocalMusicUpdated();
            }
            if (!isCancelled()) {
                notifyLocalMusicScanProgress({
                    active: true,
                    folderName: rootFolderName,
                    phase: 'hydrating',
                    totalSongs: songs.length,
                    completedSongs: savedCount,
                    discoveredSongs,
                    processedSongs: baseProcessedSongs + savedCount,
                    skippedSongs,
                    failedSongs,
                    cancelled: false,
                });
            }
            console.log(`[LocalMusic][Import] Background metadata hydration saved ${savedCount}/${songs.length} songs for "${rootFolderName}".`);
        })();
        flushInFlight = currentFlush;
        try {
            await currentFlush;
        } finally {
            if (flushInFlight === currentFlush) {
                flushInFlight = null;
            }
        }
    };

    const worker = async () => {
        while (true) {
            if (isCancelled()) {
                wasCancelled = true;
                return;
            }
            const currentIndex = nextIndex++;
            if (currentIndex >= songs.length) {
                return;
            }

            const { song: hydratedSong, failed } = await hydrateSongMetadata(songs[currentIndex]);
            if (failed) {
                failedSongs += 1;
            }

            if (isCancelled()) {
                wasCancelled = true;
                return;
            }

            pendingBatch.push(hydratedSong);

            if (pendingBatch.length >= HYDRATION_BATCH_SIZE) {
                await flushBatch();
            }
        }
    };

    try {
        const workerCount = Math.min(IMPORT_CONCURRENCY, songs.length);
        await Promise.all(Array.from({ length: workerCount }, () => worker()));
        while (pendingBatch.length > 0) {
            await flushBatch(true);
        }
        if (flushInFlight) {
            await flushInFlight;
        }
        console.log(`[LocalMusic][Import] Background metadata hydration for "${rootFolderName}" ${wasCancelled ? 'cancelled' : 'finished'} in ${formatImportDuration(performance.now() - hydrationStartedAt)}.`);
    } finally {
        notifyLocalMusicScanProgress({
            active: false,
            folderName: rootFolderName,
            phase: wasCancelled ? 'cancelled' : 'completed',
            totalSongs: songs.length,
            completedSongs: savedCount,
            discoveredSongs,
            processedSongs: baseProcessedSongs + savedCount,
            skippedSongs,
            failedSongs,
            cancelled: wasCancelled,
        });
    }
}

/**
 * Recovers and resumes metadata hydration for any local tracks whose previous scan was interrupted
 * before `embeddedMetadataVersion` reached `EMBEDDED_METADATA_VERSION`.
 */
export async function resumeInterruptedLocalLibraryScans(): Promise<number> {
    const allSongs = await getLocalSongs();
    const repairedOnStartup = repairSwappedTitleArtistAndAlbumMetadata(allSongs, allSongs);
    if (repairedOnStartup.length > 0) {
        try {
            await saveLocalSongs(repairedOnStartup);
            notifyLocalMusicUpdated();
            console.log(`[LocalMusic] Auto-repaired swapped title/artist or shared-cover album metadata for ${repairedOnStartup.length} tracks.`);
        } catch (repairErr) {
            console.warn('[LocalMusic] Failed to persist startup metadata repairs:', repairErr);
        }
    }
    const unhydratedByRoot = new Map<string, LocalSong[]>();
    for (const song of allSongs) {
        if (song.embeddedMetadataVersion === EMBEDDED_METADATA_VERSION && !song.localCoverNeedsAssetMigration) {
            continue;
        }
        const rootName = getRootFolderName(song);
        if (!rootName) continue;
        const group = unhydratedByRoot.get(rootName);
        if (group) {
            group.push(song);
        } else {
            unhydratedByRoot.set(rootName, [song]);
        }
    }

    let totalResumed = 0;
    for (const [rootFolderName, songsToHydrate] of unhydratedByRoot.entries()) {
        totalResumed += songsToHydrate.length;
        const rootTotal = allSongs.filter(song => getRootFolderName(song) === rootFolderName).length;
        void hydrateImportedSongsInBackground(rootFolderName, songsToHydrate, {
            discoveredSongs: rootTotal,
            skippedSongs: Math.max(0, rootTotal - songsToHydrate.length),
            initialFailedSongs: 0,
            alreadyHydratedChangedSongs: 0,
        }).catch(err => {
            console.warn(`[LocalMusic] Failed to resume interrupted scan for "${rootFolderName}":`, err);
        });
    }
    return totalResumed;
}


// Import folder using File System Access API (if supported)
export async function importFolder(expectedRootName?: string): Promise<LocalSong[]> {
    // Request access in the user gesture before waiting for other library writes.
    try {
        const dirHandle = await getImportDirectoryHandle(expectedRootName);
        if (!dirHandle) return [];
        return await runLocalFolderMutation(() => importFolderContents(dirHandle, expectedRootName));
    } catch (error) {
        if ((error as Error).name === 'AbortError') return [];
        throw error;
    }
}

async function importFolderContents(dirHandle: FileSystemDirectoryHandle, expectedRootName?: string): Promise<LocalSong[]> {
    try {
        const importStartedAt = performance.now();

        let rootFolderName = expectedRootName || dirHandle.name;
        let isRescanningExistingRoot = Boolean(expectedRootName);

        // If the picked directory is already imported, rescan the existing root instead of duplicating it.
        if (!expectedRootName) {
            const existingRootName = await findImportedRootForHandle(dirHandle);
            if (existingRootName) {
                rootFolderName = existingRootName;
                isRescanningExistingRoot = true;
                console.log(`[LocalMusic][Import] Directory "${dirHandle.name}" already imported as "${rootFolderName}", rescanning existing root.`);
            }
        }

        // If it's a new import (no expectedRootName), ensure the root folder name is unique
        if (!expectedRootName && !isRescanningExistingRoot) {
            const allSongs = await getLocalSongs();

            // Collect existing root folder names (the part before the first '/')
            const existingRootFolders = new Set(
                allSongs
                    .map(s => s.folderName)
                    .filter(Boolean)
                    .map(name => name!.split('/')[0])
            );

            let originalRootName = rootFolderName;
            let counter = 1;
            while (existingRootFolders.has(rootFolderName)) {
                counter++;
                rootFolderName = `${originalRootName} (${counter})`;
            }
        }

        const normalizedRoot = rootFolderName.split('/')[0] || rootFolderName;
        if (inFlightRootImports.has(normalizedRoot)) {
            return await inFlightRootImports.get(normalizedRoot)!;
        }

        const startedGlobalEpoch = globalScanCancelEpoch;
        const startedRootEpoch = cancelledScanRoots.get(normalizedRoot) || 0;
        const checkCancelled = () => isLocalLibraryScanCancelled(normalizedRoot, startedGlobalEpoch, startedRootEpoch);

        const runRootImport = async (): Promise<LocalSong[]> => {
            notifyLocalMusicScanProgress({
                active: true,
                folderName: rootFolderName,
                phase: 'discovering',
                totalSongs: 0,
                completedSongs: 0,
                discoveredSongs: 0,
                processedSongs: 0,
                skippedSongs: 0,
                failedSongs: 0,
                cancelled: false,
            });

            const traversalStartedAt = performance.now();
            const allSongs = await getLocalSongs();
            const existingRootSongs = allSongs.filter(song =>
                song.folderName === rootFolderName
                || (song.folderName && song.folderName.startsWith(`${rootFolderName}/`))
                || (song.filePath && song.filePath.startsWith(`${rootFolderName}/`))
            );
            const previousSnapshot = await getLocalLibrarySnapshot(rootFolderName);
            const diffPlan = await collectImportDiffPlan(
                rootFolderName,
                dirHandle,
                existingRootSongs,
                previousSnapshot,
                useLyricSettingsStore.getState().localLyricFormatOrder
            );
            console.log(`[LocalMusic][Import] Traversed ${diffPlan.relevantFileCount} relevant files in ${formatImportDuration(performance.now() - traversalStartedAt)}.`);

            if (checkCancelled()) {
                notifyLocalMusicScanProgress({
                    active: false,
                    folderName: rootFolderName,
                    phase: 'cancelled',
                    totalSongs: diffPlan.totalAudioFiles,
                    completedSongs: 0,
                    discoveredSongs: diffPlan.totalAudioFiles,
                    processedSongs: 0,
                    skippedSongs: diffPlan.reusedSongs.length,
                    failedSongs: 0,
                    cancelled: true,
                });
                return existingRootSongs;
            }

            // Save directory handle for persistence after a successful scan plan is built
            try {
                const dirHandles = await getDirHandles();
                dirHandles[rootFolderName] = dirHandle;
                await saveDirHandles(dirHandles);
                console.log(`[LocalMusic] Saved directory handle for ${rootFolderName}`);
            } catch (e) {
                console.error('[LocalMusic] Failed to save directory handle:', e);
            }

            const lyricIndexStartedAt = performance.now();
            console.log(`[LocalMusic][Import] Indexed ${diffPlan.lrcMap.size} lyric files, ${diffPlan.tlrcMap.size} translated lyric files, and ${diffPlan.coverMap.size} folder cover files in ${formatImportDuration(performance.now() - lyricIndexStartedAt)}.`);
            console.log(`[LocalMusic][Import] Snapshot diff for "${rootFolderName}": ${diffPlan.changedEntries.length} changed/new audio files, ${diffPlan.reusedSongs.length} unchanged audio files, ${diffPlan.removedSongs.length} removed audio files.`);

            notifyLocalMusicScanProgress({
                active: diffPlan.changedEntries.length > 0,
                folderName: rootFolderName,
                phase: diffPlan.changedEntries.length > 0 ? 'importing' : 'completed',
                totalSongs: Math.max(1, diffPlan.changedEntries.length),
                completedSongs: 0,
                discoveredSongs: diffPlan.totalAudioFiles,
                processedSongs: 0,
                skippedSongs: diffPlan.reusedSongs.length,
                failedSongs: 0,
                cancelled: false,
            });

            // Second pass: Process audio files with limited concurrency
            const metadataStartedAt = performance.now();
            const existingSongsByPath = new Map<string, LocalSong>();
            for (const song of existingRootSongs) {
                if (!existingSongsByPath.has(song.filePath)) {
                    existingSongsByPath.set(song.filePath, song);
                }
            }
            const coverBlobCache = new Map<string, Promise<PreparedLocalCoverBlob | undefined>>();
            let initialFailedSongs = 0;
            const processedSongs = await mapWithConcurrency(diffPlan.changedEntries, IMPORT_CONCURRENCY, async (entry) => {
                if (checkCancelled()) {
                    return {
                        song: null,
                        cancelled: true,
                        metrics: {
                            getFileMs: 0,
                            lyricReadMs: 0,
                            coverReadMs: 0,
                            parseMetadataMs: 0,
                            durationFallbackMs: 0,
                            usedDurationFallback: false
                        }
                    };
                }
                try {
                    const built = await buildImportedSong(
                        entry,
                        diffPlan.lrcMap,
                        diffPlan.tlrcMap,
                        diffPlan.coverMap,
                        coverBlobCache,
                        false,
                        existingSongsByPath.get(entry.relativePath)
                    );
                    if (!built.song) {
                        initialFailedSongs += 1;
                    }
                    return { ...built, cancelled: false };
                } catch (error) {
                    initialFailedSongs += 1;
                    console.error(`Failed to import file ${entry.relativePath}:`, error);
                    return {
                        song: null,
                        cancelled: false,
                        metrics: {
                            getFileMs: 0,
                            lyricReadMs: 0,
                            coverReadMs: 0,
                            parseMetadataMs: 0,
                            durationFallbackMs: 0,
                            usedDurationFallback: false
                        }
                    };
                }
            });

            // Deduplicate songsToPersist by filePath so duplicate database writes cannot occur
            const uniqueSongsByPath = new Map<string, LocalSong>();
            for (const result of processedSongs) {
                if (result.song && !uniqueSongsByPath.has(result.song.filePath)) {
                    uniqueSongsByPath.set(result.song.filePath, result.song);
                }
            }
            const songsToPersist = Array.from(uniqueSongsByPath.values());
            const aggregateMetrics = processedSongs.reduce((acc, result) => {
                acc.getFileMs += result.metrics.getFileMs;
                acc.lyricReadMs += result.metrics.lyricReadMs;
                acc.coverReadMs += result.metrics.coverReadMs;
                acc.parseMetadataMs += result.metrics.parseMetadataMs;
                acc.durationFallbackMs += result.metrics.durationFallbackMs;
                acc.durationFallbackCount += result.metrics.usedDurationFallback ? 1 : 0;
                return acc;
            }, {
                getFileMs: 0,
                lyricReadMs: 0,
                coverReadMs: 0,
                parseMetadataMs: 0,
                durationFallbackMs: 0,
                durationFallbackCount: 0
            });
            console.log(`[LocalMusic][Import] Prepared ${songsToPersist.length} changed audio files with concurrency=${IMPORT_CONCURRENCY} in ${formatImportDuration(performance.now() - metadataStartedAt)}.`);
            console.log(
                `[LocalMusic][Import] Preparation breakdown: getFile=${formatImportDuration(aggregateMetrics.getFileMs)}, ` +
                `lyrics=${formatImportDuration(aggregateMetrics.lyricReadMs)}, ` +
                `folderCover=${formatImportDuration(aggregateMetrics.coverReadMs)}, ` +
                `parseBlob=${formatImportDuration(aggregateMetrics.parseMetadataMs)}, ` +
                `durationFallback=${formatImportDuration(aggregateMetrics.durationFallbackMs)} ` +
                `(${aggregateMetrics.durationFallbackCount} files).`
            );

            if (diffPlan.removedSongs.length > 0 && !checkCancelled()) {
                const removedIds = diffPlan.removedSongs.map(song => song.id);
                removedIds.forEach(id => fileHandleMap.delete(id));
                await dbDeleteLocalSongs(removedIds);
            }

            const importedSongs = [...diffPlan.reusedSongs];
            try {
                const persistStartedAt = performance.now();
                if (songsToPersist.length > 0) {
                    repairSwappedTitleArtistAndAlbumMetadata(songsToPersist, [...diffPlan.reusedSongs, ...songsToPersist]);
                    await saveLocalSongs(songsToPersist);
                }
                if (!checkCancelled()) {
                    await saveLocalLibrarySnapshot(diffPlan.snapshot);
                }
                console.log(`[LocalMusic][Import] Persisted ${songsToPersist.length} changed songs in ${formatImportDuration(performance.now() - persistStartedAt)}.`);
                importedSongs.push(...songsToPersist);
            } catch (saveError) {
                console.error('Failed to save imported songs:', saveError);
                songsToPersist.forEach(song => fileHandleMap.delete(song.id));
                throw saveError;
            }

            console.log(`[LocalMusic][Import] Finished importing "${rootFolderName}" with ${importedSongs.length}/${diffPlan.totalAudioFiles} available songs in ${formatImportDuration(performance.now() - importStartedAt)}.`);
            if (songsToPersist.length > 0 || diffPlan.removedSongs.length > 0) {
                notifyLocalMusicUpdated();
            }

            if (checkCancelled()) {
                notifyLocalMusicScanProgress({
                    active: false,
                    folderName: rootFolderName,
                    phase: 'cancelled',
                    totalSongs: diffPlan.totalAudioFiles,
                    completedSongs: songsToPersist.length,
                    discoveredSongs: diffPlan.totalAudioFiles,
                    processedSongs: songsToPersist.length,
                    skippedSongs: diffPlan.reusedSongs.length,
                    failedSongs: initialFailedSongs,
                    cancelled: true,
                });
                return importedSongs;
            }

            const songsNeedingHydration = songsToPersist.filter(
                song => song.embeddedMetadataVersion !== EMBEDDED_METADATA_VERSION || song.localCoverNeedsAssetMigration
            );
            const alreadyHydratedChangedSongs = songsToPersist.length - songsNeedingHydration.length;

            void hydrateImportedSongsInBackground(rootFolderName, songsNeedingHydration, {
                discoveredSongs: diffPlan.totalAudioFiles,
                skippedSongs: diffPlan.reusedSongs.length,
                initialFailedSongs,
                alreadyHydratedChangedSongs,
                startedGlobalEpoch,
                startedRootEpoch,
            }).catch(error => {
                console.error(`[LocalMusic][Import] Background metadata hydration failed for "${rootFolderName}":`, error);
            });

            return importedSongs;
        };

        const importPromise = runRootImport();
        inFlightRootImports.set(normalizedRoot, importPromise);
        try {
            return await importPromise;
        } finally {
            if (inFlightRootImports.get(normalizedRoot) === importPromise) {
                inFlightRootImports.delete(normalizedRoot);
            }
        }
    } catch (error) {
        if ((error as Error).name === 'AbortError') {
            // User cancelled the picker
            return [];
        }
        throw error;
    }
}

// Helper function to normalize title for comparison
function normalizeTitle(title: string): string {
    return normalizeLyricMatchText(title).replace(/\s+/g, '');
}

// Helper function to check if two titles match
function isTitleMatch(localTitle: string, searchTitle: string): boolean {
    const normalizedLocal = normalizeTitle(localTitle);
    const normalizedSearch = normalizeTitle(searchTitle);

    // Check for exact match first
    if (normalizedLocal === normalizedSearch) {
        return true;
    }

    // Check if either title contains the other (for fuzzy matching)
    // This helps when local file is "Title-Artist" but search result is just "Title"
    if (normalizedLocal.includes(normalizedSearch) || normalizedSearch.includes(normalizedLocal)) {
        // Additional check: the shorter one should be at least 50% of the longer one
        // to avoid matching "a" with "abc"
        const minLength = Math.min(normalizedLocal.length, normalizedSearch.length);
        const maxLength = Math.max(normalizedLocal.length, normalizedSearch.length);
        if (minLength / maxLength >= 0.5) {
            return true;
        }
    }

    return false;
}

// Match lyrics for a local song using search API, respecting the configured local/online priority.
export async function matchLyrics(
    song: LocalSong,
    options: { forceRefresh?: boolean } = {},
): Promise<LyricData | null> {
    if (typeof navigator !== 'undefined' && navigator.onLine === false) {
        if (!song.matchedLyrics && !song.markedPureMusic && !song.matchedIsPureMusic) {
            const offlineSaved = await readOfflineSavedLyricsForSong(song.id, song.fileSignature);
            if (offlineSaved) {
                song.matchedLyrics = offlineSaved;
            }
        }
        return song.matchedLyrics ?? null;
    }
    await hydrateNegativeLyricMatchCache();
    if (options.forceRefresh) {
        await clearNegativeLyricMatchRecord(song.id);
    }
    // 用户标记的纯音乐不再自动匹配；与在线判定的纯音乐一样，连带的封面自动匹配也跳过。
    // 下面每次写回都带 skipIfMarkedPureMusic：匹配途中才标上的，写回时在事务里按库里的最新记录放弃。
    if (song.markedPureMusic || (song.matchedIsPureMusic && !options.forceRefresh && !shouldRefreshLocalSongLyricsFromMetadata(song))) {
        return null;
    }
    if (
        !options.forceRefresh
        && song.hasManualLyricSelection
        && Boolean(song.hasLocalLyrics || song.hasEmbeddedLyrics || song.matchedLyrics)
    ) {
        return song.matchedLyrics ?? null;
    }
    if (!options.forceRefresh && isSongOnAutomaticLyricMatchCooldown(song) && !shouldRefreshLocalSongLyricsFromMetadata(song)) {
        return null;
    }
    try {
        const catalog = await getLocalLibraryCatalogSnapshot();
        const resolvedMetadata = resolveLocalSongMetadata(song.id, catalog);
        const matchContext = buildLocalSongLyricMatchContext(song, {
            artistNames: resolvedMetadata.artists.map(artist => artist.name),
            albumName: resolvedMetadata.album?.name,
        });
        const searchQuery = buildLyricSearchQuery(matchContext.title, matchContext.artist, matchContext.album);
        const hasLocalOrEmbeddedLyrics = Boolean(
            (song.hasLocalLyrics && song.localLyricsContent)
            || (song.hasEmbeddedLyrics && song.embeddedLyricsContent)
        );
        const hasWordByWordLocalOrEmbedded = hasKnownGoodWordByWordLocalLyric(song);
        const hasLrcOnlyLocalOrEmbedded = hasLocalOrEmbeddedLyrics && !hasWordByWordLocalOrEmbedded;
        const settingsLyricSettings = useLyricSettingsStore.getState();
        const onlineFirst = settingsLyricSettings.localLyricsPriority === 'online';

        // If the song already has embedded or local TTML / word-by-word lyrics and cover, skip online lookup completely unless forced.
        if (hasWordByWordLocalOrEmbedded && !options.forceRefresh && hasLocalSongCover(song)) {
            return null;
        }

        console.log(`[LocalMusic] Searching lyrics for: "${searchQuery}"`);

        // For songs with no lyrics, or songs with embedded/local LRC seeking a better TTML/word-by-word upgrade:
        if (!hasWordByWordLocalOrEmbedded || onlineFirst || options.forceRefresh) {
            const shouldUseBestLyric = settingsLyricSettings.autoUseBestLyric || hasLrcOnlyLocalOrEmbedded || Boolean(options.forceRefresh);
            if (shouldUseBestLyric || matchContext.metadataCandidate) {
                const bestMatch = await autoMatchBestLyric(
                    matchContext.title,
                    matchContext.artist,
                    matchContext.durationMs,
                    {
                        album: matchContext.album,
                        preferredSource: shouldUseBestLyric ? settingsLyricSettings.preferredAlternativeLyricSource : undefined,
                        metadataCandidate: matchContext.metadataCandidate,
                        exactMatchOnly: Boolean(matchContext.metadataCandidate && !shouldUseBestLyric),
                    },
                );

                if (bestMatch && 'isPureMusic' in bestMatch) {
                    if (hasLocalOrEmbeddedLyrics && !options.forceRefresh) {
                        await recordAutomaticLyricMatchFailure(song);
                        return null;
                    }
                    song.matchedIsPureMusic = true;
                    song.matchedLyrics = undefined;
                    song.matchedLyricsSongId = bestMatch.id ?? matchContext.metadataCandidate?.songId;
                    song.matchedLyricsSource = bestMatch.source ?? matchContext.metadataCandidate?.source;
                    await recordAutomaticLyricMatchSuccess(song);
                    await applyMatchedMetadata(song.id, {}, { lyricsOnly: true, songPatch: song, skipIfMarkedPureMusic: true });
                    return null;
                }

                if (bestMatch && 'lyrics' in bestMatch) {
                    const isOnlineWordOrTtml = Boolean(bestMatch.lyrics.isWordByWord || bestMatch.lyrics.ttml);
                    // Protect songs that ALREADY have local/embedded TTML / word-by-word lyrics from being downgraded to line-by-line LRC.
                    if (
                        !options.forceRefresh
                        && hasWordByWordLocalOrEmbedded
                        && !isOnlineWordOrTtml
                    ) {
                        await recordAutomaticLyricMatchFailure(song);
                        return null;
                    }
                    song.matchedLyricsSongId = bestMatch.id;
                    song.matchedLyricsSource = bestMatch.source;
                    song.matchedLyricsProviderPlatform = bestMatch.matchedLyricsProviderPlatform;
                    song.matchedLyrics = bestMatch.lyrics;
                    song.matchedIsPureMusic = false;
                    void writeOfflineSavedLyricsForSong(song.id, song.fileSignature, bestMatch.lyrics);
                    await recordAutomaticLyricMatchSuccess(song);

                    if (matchContext.metadataCandidate) {
                        await applyMatchedMetadata(song.id, {}, { lyricsOnly: true, songPatch: song, skipIfMarkedPureMusic: true });
                        return bestMatch.lyrics;
                    }

                    const matchedMetadata = normalizeLyricMatchMetadataCandidate(
                        bestMatch.source,
                        bestMatch.song,
                        {
                            title: matchContext.title,
                            artist: matchContext.artist,
                            album: matchContext.album,
                            durationMs: matchContext.durationMs,
                        },
                    );
                    const coverUrl = matchedMetadata.coverUrl;
                    const enrichedImportedMetadata = (!song.importedMetadata?.albumName && matchedMetadata.album?.name)
                        ? { ...song.importedMetadata, albumName: matchedMetadata.album.name }
                        : song.importedMetadata;
                    song.importedMetadata = enrichedImportedMetadata;
                    await applyMatchedMetadata(song.id, {
                        source: matchedMetadata.source,
                        songId: matchedMetadata.songId,
                        title: matchedMetadata.title,
                        artists: matchedMetadata.artists,
                        album: matchedMetadata.album,
                        coverUrl,
                    }, {
                        songPatch: {
                            ...song,
                            importedMetadata: enrichedImportedMetadata,
                            useOnlineCover: Boolean(coverUrl && !hasLocalSongCover(song)),
                        },
                        protectOrigins: ['manual', 'manual-match', 'split'],
                        skipIfMarkedPureMusic: true,
                    });
                    return bestMatch.lyrics;
                }
            }
        } else if (matchContext.metadataCandidate) {
            return null;
        }

        // If the song already has local/embedded lyrics (TTML or LRC) and already has a cover, do not fall back to plain-LRC catalog search.
        if (hasLocalOrEmbeddedLyrics && !options.forceRefresh && hasLocalSongCover(song)) {
            await recordAutomaticLyricMatchFailure(song);
            return null;
        }

        // Search on Netease
        let searchPage: { items?: SongResult[] } | undefined;
        try {
            searchPage = await getOnlineMusicProvider('netease')?.search?.searchSongs(searchQuery, 50, 0);
        } catch (catalogSearchError) {
            console.warn('[LocalMusic] Secondary catalog search unavailable:', catalogSearchError);
        }

        if (!searchPage?.items?.length) {
            console.warn(`[LocalMusic] No search results for: "${searchQuery}"`);
            await recordAutomaticLyricMatchFailure(song);
            return null;
        }

        // Try to find a song with matching title
        const localTitle = matchContext.title;
        const matchedSong = searchPage.items.find(candidate => isTitleMatch(localTitle, candidate.name));

        // If no exact title match found, return null to trigger manual selection
        if (!matchedSong) {
            console.log(`[LocalMusic] No exact title match found for: "${localTitle}". Manual selection required.`);
            await recordAutomaticLyricMatchFailure(song);
            return null;
        }

        const matchedMetadata = getProviderSongMetadata(matchedSong, 'netease');
        console.log(`[LocalMusic] Found exact title match: ${matchedSong.name} by ${matchedMetadata.artists.map(artist => artist.name).join(', ')}`);

        // Preserve local and embedded lyrics when the configured priority keeps them first.
        if (!onlineFirst && ((song.hasLocalLyrics && song.localLyricsContent) || (song.hasEmbeddedLyrics && song.embeddedLyricsContent))) {
            console.log(`[LocalMusic] Local/embedded lyrics exist, skipping online lyrics fetch. Only fetching cover/metadata.`);

            // Only update metadata and cover, preserve local lyrics
            const coverUrl = matchedMetadata.coverUrl;
            await applyMatchedMetadata(song.id, {
                source: 'netease',
                songId: matchedSong.id,
                title: matchedSong.name,
                artists: matchedMetadata.artists,
                album: matchedMetadata.album,
                coverUrl: coverUrl?.replace('http:', 'https:'),
            }, {
                songPatch: { ...song, useOnlineCover: Boolean(coverUrl && !hasLocalSongCover(song)) },
                protectOrigins: ['manual', 'manual-match', 'split'],
                skipIfMarkedPureMusic: true,
            });

            // Return null to indicate no NEW lyrics were fetched (local lyrics are used)
            return null;
        }

        // Fetch lyrics (only when NO local lyrics)
        const processed = await getOnlineMusicProvider('netease')?.lyrics?.getLyrics(matchedSong);
        if (!processed) {
            await recordAutomaticLyricMatchFailure(song);
            return null;
        }

        song.matchedLyricsSongId = matchedSong.id;
        song.matchedLyricsSource = 'netease';
        song.matchedLyrics = processed.lyrics || undefined;
        song.matchedIsPureMusic = processed.isPureMusic;
        if (processed.lyrics) {
            void writeOfflineSavedLyricsForSong(song.id, song.fileSignature, processed.lyrics);
        }
        await recordAutomaticLyricMatchSuccess(song);

        if (matchContext.metadataCandidate) {
            await applyMatchedMetadata(song.id, {}, { lyricsOnly: true, songPatch: song, skipIfMarkedPureMusic: true });
            return processed.lyrics;
        }

        const coverUrl = matchedMetadata.coverUrl;
        await applyMatchedMetadata(song.id, {
            source: 'netease',
            songId: matchedSong.id,
            title: matchedSong.name,
            artists: matchedMetadata.artists,
            album: matchedMetadata.album,
            coverUrl: coverUrl?.replace('http:', 'https:'),
        }, {
            songPatch: { ...song, useOnlineCover: Boolean(coverUrl && !hasLocalSongCover(song)) },
            protectOrigins: ['manual', 'manual-match', 'split'],
            skipIfMarkedPureMusic: true,
        });
        return processed.lyrics;
    } catch (error) {
        console.error('[LocalMusic] Failed to match lyrics:', error);
        return null;
    }
}

// Delete local song
export async function deleteLocalSong(id: string): Promise<void> {
    // Remove fileHandle from memory
    fileHandleMap.delete(id);
    await Promise.all([
        dbDeleteLocalSong(id),
        removeCachedCover(`cover_local_${id}`),
    ]);
}

function getRootFolderName(song: LocalSong): string | null {
    const pathLike = song.filePath || song.folderName;
    if (!pathLike) return null;

    const [rootFolderName] = pathLike.split('/');
    return rootFolderName || null;
}

async function resolveFileHandleFromDirHandle(
    dirHandle: FileSystemDirectoryHandle,
    relativePathFromRoot: string
): Promise<FileSystemFileHandle> {
    const pathSegments = relativePathFromRoot.split('/').filter(Boolean);
    if (pathSegments.length === 0) {
        throw new Error('Cannot resolve a file handle from an empty path.');
    }

    const fileName = pathSegments[pathSegments.length - 1];
    const directorySegments = pathSegments.slice(0, -1);

    let currentDir = dirHandle;
    for (const segment of directorySegments) {
        currentDir = await currentDir.getDirectoryHandle(segment);
    }

    return await currentDir.getFileHandle(fileName);
}

async function recoverFileHandleFromPersistedDirectory(song: LocalSong): Promise<FileSystemFileHandle | null> {
    const rootFolderName = getRootFolderName(song);
    if (!rootFolderName || !song.filePath) {
        return null;
    }

    const dirHandles = await getDirHandles();
    const rootDirHandle = dirHandles[rootFolderName];
    if (!rootDirHandle) {
        return null;
    }

    const permissionAwareHandle = rootDirHandle as FileSystemDirectoryHandle & {
        queryPermission: (descriptor: { mode: 'read' | 'readwrite'; }) => Promise<PermissionState>;
    };
    const permission = await permissionAwareHandle.queryPermission({ mode: 'read' });
    if (permission !== 'granted') {
        return null;
    }

    const relativePathFromRoot = song.filePath.startsWith(`${rootFolderName}/`)
        ? song.filePath.slice(rootFolderName.length + 1)
        : song.filePath;

    try {
        const recoveredHandle = await resolveFileHandleFromDirHandle(rootDirHandle, relativePathFromRoot);
        fileHandleMap.set(song.id, recoveredHandle);
        song.fileHandle = recoveredHandle;
        if (isAndroidSafFileHandle(recoveredHandle)) {
            const uriChanged = song.safContentUri !== recoveredHandle.contentUri
                || song.safTreeUri !== recoveredHandle.treeUri;
            song.safContentUri = recoveredHandle.contentUri;
            song.safTreeUri = recoveredHandle.treeUri;
            song.safDocumentId = recoveredHandle.documentId;
            if (uriChanged) {
                await saveLocalSong(song);
            }
        }
        return recoveredHandle;
    } catch (error) {
        console.warn(`[LocalMusic] Failed to recover file handle for ${song.filePath}:`, error);
        return null;
    }
}

async function getAccessibleFileHandle(song: LocalSong): Promise<FileSystemFileHandle | null> {
    let fileHandle = fileHandleMap.get(song.id);

    if (!fileHandle && song.fileHandle) {
        fileHandle = song.fileHandle;
        fileHandleMap.set(song.id, fileHandle);
    }

    if (fileHandle) {
        return fileHandle;
    }

    // Fast O(1) reconstruction from persisted Android SAF document URI when available.
    if (song.safContentUri && song.safTreeUri && hasFoliaAndroidBridge()) {
        const directHandle = createAndroidSafFileHandle(
            {
                name: song.fileName,
                relativePath: song.filePath,
                kind: 'file',
                documentId: song.safDocumentId || song.safContentUri,
                contentUri: song.safContentUri,
                mimeType: song.mimeType,
                size: song.fileSize,
                lastModified: song.fileLastModified || 0,
            },
            song.safTreeUri,
        );
        fileHandleMap.set(song.id, directHandle);
        song.fileHandle = directHandle;
        return directHandle;
    }

    return await recoverFileHandleFromPersistedDirectory(song);
}

async function cleanupDirHandleIfUnused(rootFolderName: string): Promise<void> {
    if ((await getLocalLibrarySnapshot(rootFolderName))?.ignoredFolderPaths?.length) return;
    const allSongs = await getLocalSongs();
    const stillUsed = allSongs.some(song => {
        const songRoot = getRootFolderName(song);
        return songRoot === rootFolderName;
    });

    if (!stillUsed) {
        await deleteDirHandle(rootFolderName);
        await deleteLocalLibrarySnapshot(rootFolderName);
        console.log(`[LocalMusic] Removed persisted directory handle for ${rootFolderName}`);
    }
}

// Get audio blob from local song using fileHandle
// Returns blob URL if fileHandle exists, null otherwise

/**
 * Pre-stages the currently playing and next queued local SAF audio tracks into
 * context.getCacheDir()/saf_audio_stage/ using a 512 KB copy buffer so playback reads from a
 * contiguous local file instead of making hundreds of IPC calls through Android's SAF provider.
 */
export async function prestageLocalSongsForPlayback(
    songs: ReadonlyArray<LocalSong | null | undefined>,
): Promise<void> {
    if (!hasFoliaAndroidBridge()) return;
    const uris: string[] = [];
    for (const candidate of songs) {
        if (!candidate) continue;
        if (candidate.safContentUri && candidate.safContentUri.startsWith("content://")) {
            if (!uris.includes(candidate.safContentUri)) {
                uris.push(candidate.safContentUri);
            }
            continue;
        }
        const handle = await getAccessibleFileHandle(candidate);
        if (handle && isAndroidSafFileHandle(handle) && handle.contentUri.startsWith("content://")) {
            if (!uris.includes(handle.contentUri)) {
                uris.push(handle.contentUri);
            }
        }
    }
    if (uris.length > 0) {
        await prestageAndroidSafAudioTracks(uris);
    }
}

export async function getAudioFromLocalSong(song: LocalSong): Promise<string | null> {
    const resolvePlayableSource = async (handle: FileSystemFileHandle): Promise<string> => {
        if (isAndroidSafFileHandle(handle) && handle.canStreamDirectly()) {
            const readable = await handle.verifyReadable();
            if (!readable) {
                throw new Error(`Android SAF file is unreadable or missing: ${song.filePath}`);
            }
            void prestageAndroidSafAudioTracks([handle.contentUri]);
            return handle.getPlayableStreamUrl();
        }
        const file = await handle.getFile();
        return await getAudioFromFile(file);
    };

    const fileHandle = await getAccessibleFileHandle(song);

    if (fileHandle) {
        try {
            return await resolvePlayableSource(fileHandle);
        } catch (error) {
            console.error('[LocalMusic] Failed to get file from handle:', error);
            // File may have been moved or the stored handle may have become stale.
            fileHandleMap.delete(song.id);
        }
    }

    const recoveredHandle = await recoverFileHandleFromPersistedDirectory(song);
    if (recoveredHandle) {
        try {
            return await resolvePlayableSource(recoveredHandle);
        } catch (error) {
            console.error('[LocalMusic] Failed to get file from recovered directory handle:', error);
            fileHandleMap.delete(song.id);
        }
    }

    // No accessible handle available - permission may need to be restored or the file moved.
    console.warn(`[LocalMusic] No accessible handle for song ${song.id}. Permission restore or re-import is required.`);
    return null;
}

/** Resolves the current File for playback recovery without changing the song or minting a URL. */
export async function getFileFromLocalSong(song: LocalSong): Promise<File | null> {
    const fileHandle = await getAccessibleFileHandle(song);
    if (fileHandle) {
        try {
            return await fileHandle.getFile();
        } catch (error) {
            console.warn(`[LocalMusic] Failed to read local recovery input for ${song.id}:`, error);
            fileHandleMap.delete(song.id);
        }
    }

    const recoveredHandle = await recoverFileHandleFromPersistedDirectory(song);
    if (!recoveredHandle) return null;
    try {
        return await recoveredHandle.getFile();
    } catch (error) {
        console.warn(`[LocalMusic] Failed to read recovered local input for ${song.id}:`, error);
        fileHandleMap.delete(song.id);
        return null;
    }
}

/**
 * The local file's raw bytes, for callers that need the audio itself rather than a URL to it.
 *
 * Automix separation is the caller: it must not mint a blob URL only to read it once and then have to
 * revoke it, and a local file never enters the online media cache, so its bytes are reachable only
 * from its own handle. Mirrors getAudioFromLocalSong's resolution (accessible handle, else a recover)
 * but returns the ArrayBuffer. Null when no handle can be reached - permission not restored, or moved.
 */
export async function getLocalSongArrayBuffer(song: LocalSong): Promise<ArrayBuffer | null> {
    const fileHandle = await getAccessibleFileHandle(song);
    if (!fileHandle) {
        console.warn(`[LocalMusic] No accessible handle for song ${song.id} (automix bytes)`);
        return null;
    }
    try {
        return await (await fileHandle.getFile()).arrayBuffer();
    } catch (error) {
        console.error('[LocalMusic] Failed to read local bytes:', error);
        fileHandleMap.delete(song.id);
        return null;
    }
}

// Extracts and persists one song's embedded cover (and any unhydrated embedded TTML/LRC lyrics) on playback.
async function extractAndPersistSongCover(
    song: LocalSong,
    fileHandle: FileSystemFileHandle,
): Promise<LocalSong> {
    let metadata: EmbeddedMetadata;
    let fileRevision: string;
    const needsEmbeddedLyrics = !song.hasLocalLyrics && !song.hasEmbeddedLyrics && song.embeddedMetadataVersion !== EMBEDDED_METADATA_VERSION;
    if (isAndroidSafFileHandle(fileHandle)) {
        const stat = fileHandle.getStatMetadata();
        fileRevision = `${stat.size}:${stat.lastModified}`;
        if (!needsEmbeddedLyrics && songsWithoutEmbeddedCover.get(song.id) === fileRevision) return song;
        const extracted = await extractSafHandleEmbeddedMetadata(fileHandle, true);
        metadata = extracted.metadata;
    } else {
        const file = await fileHandle.getFile();
        fileRevision = `${file.size}:${file.lastModified}`;
        if (!needsEmbeddedLyrics && songsWithoutEmbeddedCover.get(song.id) === fileRevision) return song;
        metadata = await extractEmbeddedMetadata(file, true);
    }
    const foundLyrics = Boolean(metadata.lyrics && metadata.lyrics.trim());
    const foundTranslationLyrics = Boolean(metadata.translationLyrics && metadata.translationLyrics.trim());
    const hasEmbeddedTagMetadata = Boolean(
        metadata.title
        || metadata.artist
        || metadata.artists?.length
        || metadata.album
        || metadata.albumArtist
        || metadata.year
        || metadata.genre
    );
    const filenameMetadata = extractMetadataFromFilename(song.fileName);
    const nextImportedMetadata = hasEmbeddedTagMetadata
        ? buildImportedMetadataSnapshot({
            fileName: song.fileName,
            embeddedTitle: metadata.title || (song.importedMetadata?.titleSource === 'embedded' ? song.importedMetadata.title : undefined),
            fallbackTitle: filenameMetadata.title || song.importedMetadata?.title,
            embeddedArtist: metadata.artist,
            embeddedArtists: metadata.artists?.length ? metadata.artists : song.importedMetadata?.artistNames,
            fallbackArtist: filenameMetadata.artist,
            embeddedAlbum: metadata.album || song.importedMetadata?.albumName,
            embeddedAlbumArtist: metadata.albumArtist || song.importedMetadata?.albumArtist,
            embeddedYear: metadata.year ?? song.importedMetadata?.year,
            embeddedGenre: metadata.genre || song.importedMetadata?.genre,
            embeddedCodec: metadata.codec || song.importedMetadata?.codec,
        })
        : song.importedMetadata;
    const nextTitle = song.titleOrigin === 'import' && nextImportedMetadata
        ? nextImportedMetadata.title
        : song.title;
    const nextDuration = metadata.duration || song.duration || 0;

    if (!metadata.cover || !metadata.coverAssetId) {
        songsWithoutEmbeddedCover.set(song.id, fileRevision);
        song.hasNoEmbeddedCover = true;
        if (foundLyrics || foundTranslationLyrics || hasEmbeddedTagMetadata || needsEmbeddedLyrics) {
            const updatedNoCoverSong: LocalSong = {
                ...song,
                title: nextTitle,
                duration: nextDuration,
                importedMetadata: nextImportedMetadata,
                albumArtist: metadata.albumArtist || song.albumArtist,
                trackNumber: metadata.trackNumber ?? song.trackNumber,
                discNumber: metadata.discNumber ?? song.discNumber,
                year: metadata.year ?? song.year,
                genre: metadata.genre || song.genre,
                codec: metadata.codec || song.codec,
                bitrate: metadata.bitrate || song.bitrate,
                hasNoEmbeddedCover: true,
                hasEmbeddedLyrics: foundLyrics || Boolean(song.hasEmbeddedLyrics),
                embeddedLyricsContent: foundLyrics ? metadata.lyrics : song.embeddedLyricsContent,
                hasEmbeddedTranslationLyrics: foundTranslationLyrics || Boolean(song.hasEmbeddedTranslationLyrics),
                embeddedTranslationLyricsContent: foundTranslationLyrics ? metadata.translationLyrics : song.embeddedTranslationLyricsContent,
                embeddedMetadataVersion: EMBEDDED_METADATA_VERSION,
                fileHandle,
            };
            Object.assign(song, updatedNoCoverSong);
            await saveLocalSong(updatedNoCoverSong);
            return updatedNoCoverSong;
        }
        return song;
    }
    songsWithoutEmbeddedCover.delete(song.id);
    stageLocalCoverAsset(metadata.coverAssetId, metadata.cover);

    const updatedSong: LocalSong = {
        ...song,
        title: nextTitle,
        duration: nextDuration,
        importedMetadata: nextImportedMetadata,
        albumArtist: metadata.albumArtist || song.albumArtist,
        trackNumber: metadata.trackNumber ?? song.trackNumber,
        discNumber: metadata.discNumber ?? song.discNumber,
        year: metadata.year ?? song.year,
        genre: metadata.genre || song.genre,
        codec: metadata.codec || song.codec,
        bitrate: metadata.bitrate || song.bitrate,
        localCoverAssetId: metadata.coverAssetId,
        localCoverSource: 'embedded',
        hasNoEmbeddedCover: false,
        hasEmbeddedLyrics: foundLyrics || Boolean(song.hasEmbeddedLyrics),
        embeddedLyricsContent: foundLyrics ? metadata.lyrics : song.embeddedLyricsContent,
        hasEmbeddedTranslationLyrics: foundTranslationLyrics || Boolean(song.hasEmbeddedTranslationLyrics),
        embeddedTranslationLyricsContent: foundTranslationLyrics ? metadata.translationLyrics : song.embeddedTranslationLyricsContent,
        embeddedMetadataVersion: EMBEDDED_METADATA_VERSION,
        fileHandle,
    };
    Object.assign(song, updatedSong);
    await saveLocalSong(updatedSong);
    return updatedSong;
}

export async function ensureLocalSongCoverAsset(song: LocalSong): Promise<LocalSong> {
    const needsEmbeddedLyricsHydration = Boolean(
        !song.hasLocalLyrics
        && !song.hasEmbeddedLyrics
        && song.embeddedMetadataVersion !== EMBEDDED_METADATA_VERSION
        && (song.fileHandle || song.safContentUri || fileHandleMap.has(song.id))
    );
    if (!needsEmbeddedLyricsHydration) {
        if (song.localCoverAssetId && await hasLocalCoverBinary(song.localCoverAssetId)) return song;
        if (song.localCoverSource === 'folder') return song;
        if (song.hasNoEmbeddedCover && !song.localCoverNeedsAssetMigration) return song;
    }

    if (!localCoverAssetRequestMap.has(song.id)) {
        localCoverAssetRequestMap.set(song.id, (async () => {
            const fileHandle = await getAccessibleFileHandle(song);
            if (!fileHandle) {
                return song;
            }

            try {
                return await extractAndPersistSongCover(song, fileHandle);
            } catch (error) {
                console.warn(`[LocalMusic] Failed to ensure embedded cover for ${song.fileName}:`, error);
                fileHandleMap.delete(song.id);

                try {
                    const recoveredHandle = await recoverFileHandleFromPersistedDirectory(song);
                    if (!recoveredHandle) {
                        return song;
                    }

                    return await extractAndPersistSongCover(song, recoveredHandle);
                } catch (recoveryError) {
                    console.warn(`[LocalMusic] Failed to recover embedded cover for ${song.fileName}:`, recoveryError);
                    return song;
                }
            } finally {
                localCoverAssetRequestMap.delete(song.id);
            }
        })());
    }

    return await localCoverAssetRequestMap.get(song.id)!;
}

// Get audio blob from File object (for file input imports)
export async function getAudioFromFile(file: File): Promise<string> {
    const url = createSafeObjectUrl(await repairFlacMetadata(file, true));
    if (!url) throw new TypeError('Local audio source must be a File or Blob');
    return url;
}

// Delete songs by their specific IDs
export async function deleteSongsByIds(songIds: string[]): Promise<void> {
    const uniqueSongIds = Array.from(new Set(songIds));
    if (uniqueSongIds.length === 0) return;
    const allSongs = await getLocalSongs();
    const deletedIdSet = new Set(uniqueSongIds);
    const affectedRoots = new Set(
        allSongs
            .filter(song => deletedIdSet.has(song.id))
            .map(getRootFolderName)
            .filter((root): root is string => Boolean(root)),
    );
    uniqueSongIds.forEach(id => {
        fileHandleMap.delete(id);
        localCoverAssetRequestMap.delete(id);
        songsWithoutEmbeddedCover.delete(id);
    });
    await Promise.all([
        dbDeleteLocalSongs(uniqueSongIds),
        ...uniqueSongIds.map(id => removeCachedCover(`cover_local_${id}`)),
    ]);
    await removeDeletedSongIdsFromPlaylists(uniqueSongIds);
    await Promise.all(Array.from(affectedRoots).map(cleanupDirHandleIfUnused));
    notifyLocalMusicUpdated();
    console.log(`[LocalMusic] Deleted ${uniqueSongIds.length} songs by ID`);
}

// Removes an imported root from the app, including empty roots, without deleting disk files.
export function removeImportedRoot(rootFolderName: string): Promise<void> {
    return runLocalFolderMutation(() => removeImportedRootContents(rootFolderName));
}

async function removeImportedRootContents(rootFolderName: string): Promise<void> {
    const normalizedRoot = normalizeLocalFolderPath(rootFolderName).split('/')[0];
    if (!normalizedRoot) return;
    removedRootGenerations.set(normalizedRoot, (removedRootGenerations.get(normalizedRoot) || 0) + 1);

    const allSongs = await getLocalSongs();
    const songIds = allSongs
        .filter(song => getRootFolderName(song) === normalizedRoot)
        .map(song => song.id);

    if (songIds.length > 0) {
        await deleteSongsByIds(songIds);
    }
    await Promise.all([
        deleteDirHandle(normalizedRoot),
        deleteLocalLibrarySnapshot(normalizedRoot),
    ]);
    notifyLocalMusicUpdated();
}

// Resync folder: refresh an imported folder in place using the persisted root handle
export async function resyncFolder(folderName: string): Promise<LocalSong[] | null> {
    // Only root imports have persisted directory handles. Derived child folders
    // should resync through their imported root folder handle.
    const rootFolderName = folderName.split('/')[0] || folderName;
    const importedSongs = await importFolder(rootFolderName);

    // If user cancelled (empty array), return null to indicate cancellation
    if (importedSongs.length === 0) {
        return null;
    }

    return importedSongs;
}

function getLocalSongRootFolderName(song: LocalSong): string | null {
    const sourcePath = song.folderName || song.filePath;
    const rootFolderName = sourcePath.split('/')[0]?.trim();
    return rootFolderName || null;
}

// Resyncs all imported local roots once, even when the song list contains nested folders.
export async function resyncAllFolders(): Promise<LocalSong[] | null> {
    const allSongs = await getLocalSongs();
    const handles = await getDirHandles();
    const rootFolderNames = Array.from(new Set(
        [...Object.keys(handles), ...allSongs
            .map(getLocalSongRootFolderName)
            .filter((rootFolderName): rootFolderName is string => Boolean(rootFolderName))]
    ));

    if (rootFolderNames.length === 0) {
        return null;
    }

    const importedSongs: LocalSong[] = [];
    for (const rootFolderName of rootFolderNames) {
        const rootSongs = await importFolder(rootFolderName);
        importedSongs.push(...rootSongs);
    }

    return importedSongs;
}

// Clear the app's ignore flag and rescan immediately; disk ignore rules still apply.
export async function clearFolderIgnore(folderName: string): Promise<void> {
    const rootFolderName = normalizeLocalFolderPath(folderName).split('/')[0];
    const dirHandle = await getImportDirectoryHandle(rootFolderName);
    if (!dirHandle) return;
    return runLocalFolderMutation(async () => {
        await setLocalFolderIgnored(folderName, false);
        await importFolderContents(dirHandle, rootFolderName);
    });
}

// Delete all songs from a specific folder (and its nested children)
export function deleteFolderSongs(folderName: string): Promise<void> {
    return runLocalFolderMutation(() => deleteFolderContents(folderName));
}

async function deleteFolderContents(folderName: string): Promise<void> {
    folderName = normalizeLocalFolderPath(folderName);
    if (!folderName.includes('/')) return removeImportedRootContents(folderName);
    await setLocalFolderIgnored(folderName, true);
    // Get all local songs
    const allSongs = await getLocalSongs();

    // Filter songs that belong to this folder OR are nested under it
    const songsToDelete = allSongs.filter(song =>
        song.folderName === folderName || (song.folderName && song.folderName.startsWith(`${folderName}/`))
    );

    const songIdsToDelete = songsToDelete.map(song => song.id);
    songIdsToDelete.forEach(id => {
        fileHandleMap.delete(id);
        localCoverAssetRequestMap.delete(id);
        songsWithoutEmbeddedCover.delete(id);
    });
    await Promise.all([
        dbDeleteLocalSongs(songIdsToDelete),
        ...songIdsToDelete.map(id => removeCachedCover(`cover_local_${id}`)),
    ]);
    await removeDeletedSongIdsFromPlaylists(songIdsToDelete);

    notifyLocalMusicUpdated();
    console.log(`[LocalMusic] Deleted ${songsToDelete.length} songs from folder tree: ${folderName}`);
}

src/services/onlineMetadataSearchService:
import type { LocalSong, LyricProviderSource, SongResult } from '../types';
import type { LocalSongMetadataSource } from '../types/localLibrary';
import { getProviderSongMetadata } from './onlineMusic/songMetadata';
import { getLyricSourceAccess } from '../utils/lyrics/lyricMatchSources';
import { calculateMatchScoreDetails } from '../utils/lyrics/matchScore';
import { buildLyricSearchQuery } from '../utils/lyrics/searchQuery';
import {
    getMatchResultAlbumId,
    getMatchResultAlbumName,
    getMatchResultArtistEntities,
    getMatchResultCoverUrl,
} from '../utils/lyrics/matchResult';

// src/services/onlineMetadataSearchService.ts
// Searches song metadata without invoking any lyric provider or lyric download path.

export type OnlineMetadataSource = LocalSongMetadataSource;

export interface OnlineMetadataSearchTarget {
    title: string;
    artist: string;
    album?: string;
    durationMs: number;
}

export interface OnlineMetadataCandidate {
    source: OnlineMetadataSource;
    songId: number | string;
    title: string;
    artists: Array<{ id?: number | string; name: string }>;
    album?: { id?: number | string; name: string };
    coverUrl?: string;
    durationMs: number;
    score: number;
    titleMatched: boolean;
    durationMatched: boolean | null;
    raw: SongResult;
}

const stripAudioExtension = (fileName: string) => fileName.replace(/\.(mp3|flac|m4a|wav|ogg|opus|aac)$/i, '');

export const buildLocalSongMetadataSearchTarget = (song: LocalSong): OnlineMetadataSearchTarget => ({
    title: song.title || stripAudioExtension(song.fileName),
    artist: song.titleOrigin === 'import'
        ? song.importedMetadata.artistNames.join(', ')
        : song.onlineMetadata?.artists.map(artist => artist.name).join(', ') || song.importedMetadata.artistNames.join(', '),
    album: song.titleOrigin === 'import'
        ? song.importedMetadata.albumName || ''
        : song.onlineMetadata?.album?.name || song.importedMetadata.albumName || '',
    durationMs: song.duration || 0,
});

export const buildLocalSongMetadataSearchQuery = (song: LocalSong): string => {
    const target = buildLocalSongMetadataSearchTarget(song);
    return buildLyricSearchQuery(target.title, target.artist, target.album);
};

export const normalizeOnlineMetadataCandidate = (
    source: OnlineMetadataSource,
    result: SongResult,
    target: OnlineMetadataSearchTarget,
): OnlineMetadataCandidate => {
    const details = calculateMatchScoreDetails(target, result);
    const albumName = getMatchResultAlbumName(result).trim();
    const albumId = getMatchResultAlbumId(result);
    return {
        source,
        songId: source === 'qq' && result.qqMid
            ? result.qqMid
            : source === 'kugou' && result.kgHash
                ? result.kgHash
                : result.id,
        title: result.name || '',
        artists: getMatchResultArtistEntities(result),
        album: albumName ? { id: albumId, name: albumName } : undefined,
        coverUrl: getMatchResultCoverUrl(result, source) || undefined,
        durationMs: getProviderSongMetadata(result, source).durationMs,
        score: details.score,
        titleMatched: details.titleMatched,
        durationMatched: details.durationMatched,
        raw: result,
    };
};

export const normalizeLyricMatchMetadataCandidate = (
    lyricSource: LyricProviderSource,
    result: SongResult,
    target: OnlineMetadataSearchTarget,
): OnlineMetadataCandidate => {
    const source: OnlineMetadataSource = lyricSource === 'amll'
        ? result.amllDbPlatform === 'qq' ? 'qq' : 'netease'
        : lyricSource;
    return normalizeOnlineMetadataCandidate(source, result, target);
};

const throwIfAborted = (signal?: AbortSignal) => {
    if (!signal?.aborted) return;
    const error = new Error('Metadata matching was cancelled');
    error.name = 'AbortError';
    throw error;
};

// Stops waiting immediately when a provider client cannot receive AbortSignal directly.
const waitForProvider = async <T>(request: Promise<T>, signal?: AbortSignal): Promise<T> => {
    if (!signal) return await request;
    throwIfAborted(signal);
    return await new Promise<T>((resolve, reject) => {
        const abort = () => {
            const error = new Error('Metadata matching was cancelled');
            error.name = 'AbortError';
            reject(error);
        };
        signal.addEventListener('abort', abort, { once: true });
        request.then(
            value => {
                signal.removeEventListener('abort', abort);
                resolve(value);
            },
            error => {
                signal.removeEventListener('abort', abort);
                reject(error);
            },
        );
    });
};

export async function searchOnlineMetadata(
    source: OnlineMetadataSource,
    query: string,
    target: OnlineMetadataSearchTarget,
    options: { limit?: number; signal?: AbortSignal } = {},
): Promise<OnlineMetadataCandidate[]> {
    const safeQuery = query.trim();
    if (!safeQuery) return [];
    throwIfAborted(options.signal);
    const limit = options.limit ?? 10;
    const results = await waitForProvider(getLyricSourceAccess(source).search(safeQuery, limit, target), options.signal);
    throwIfAborted(options.signal);
    return results
        .map(result => normalizeOnlineMetadataCandidate(source, result, target))
        .sort((left, right) => right.score - left.score)
        .slice(0, limit);
}

// Preserves the established NetEase-to-QQ fallback and appends KuGou as the final provider-backed source.
export async function findAutomaticOnlineMetadataCandidate(
    song: LocalSong,
    signal?: AbortSignal,
): Promise<OnlineMetadataCandidate | null> {
    const target = buildLocalSongMetadataSearchTarget(song);
    const query = buildLocalSongMetadataSearchQuery(song);
    let neteaseCandidates: OnlineMetadataCandidate[] = [];
    try {
        neteaseCandidates = await searchOnlineMetadata('netease', query, target, { limit: 10, signal });
    } catch (error) {
        if ((error as Error).name === 'AbortError') throw error;
        console.warn('[LocalMusic] NetEase metadata search failed, falling back to QQ:', error);
    }
    if (neteaseCandidates[0]?.titleMatched) return neteaseCandidates[0];
    try {
        const qqCandidates = await searchOnlineMetadata('qq', query, target, { limit: 10, signal });
        if (qqCandidates[0]?.titleMatched) return qqCandidates[0];
    } catch (error) {
        if ((error as Error).name === 'AbortError') throw error;
        console.warn('[LocalMusic] QQ metadata search failed, falling back to KuGou:', error);
    }
    try {
        const kugouCandidates = await searchOnlineMetadata('kugou', query, target, { limit: 10, signal });
        if (kugouCandidates[0]?.titleMatched) return kugouCandidates[0];
    } catch (error) {
        if ((error as Error).name === 'AbortError') throw error;
    }
    try {
        const lrclibCandidates = await searchOnlineMetadata('lrclib', query, target, { limit: 10, signal });
        if (lrclibCandidates[0]?.titleMatched) return lrclibCandidates[0];
    } catch (error) {
        if ((error as Error).name === 'AbortError') throw error;
    }
    return null;
}

