// src/utils/platform.ts
// One place to answer "is this a Mac", "is this Windows", "is this Electron", and "is this a
// Capacitor native app", so keyboard handling, shortcut hints, service-worker registration, and
// platform adapters can never disagree about the active host runtime.

interface CapacitorGlobal {
    getPlatform?: () => string;
    isNativePlatform?: () => boolean;
    isPluginAvailable?: (name: string) => boolean;
}

const getCapacitorGlobal = (): CapacitorGlobal | null => {
    const globalCandidate = typeof globalThis !== 'undefined'
        ? (globalThis as { Capacitor?: CapacitorGlobal }).Capacitor
        : undefined;
    const windowCandidate = typeof window !== 'undefined'
        ? (window as unknown as { Capacitor?: CapacitorGlobal }).Capacitor
        : undefined;
    const candidate = globalCandidate ?? windowCandidate;
    return candidate && typeof candidate === 'object' ? candidate : null;
};

export const isMacPlatform = typeof navigator !== 'undefined'
    && navigator.userAgent.toLowerCase().includes('mac');

/**
 * Whether this is Windows. Pausing for voice input is for the Windows desktop app only: the
 * settings window asks this before it offers the row, the settings search before it lists it, and
 * the command palette before it offers the command.
 */
export const runsOnWindows = (): boolean => (
    typeof navigator !== 'undefined' && navigator.userAgent.toLowerCase().includes('win')
);

/** Whether the renderer is running inside the Electron desktop shell. */
export const isElectronPlatform = (): boolean => (
    typeof window !== 'undefined' && Boolean((window as unknown as { electron?: { isElectron?: boolean } }).electron)
);

/** Returns the active Capacitor platform identifier ('android', 'ios', or 'web'). */
export const getCapacitorPlatform = (): string => {
    const cap = getCapacitorGlobal();
    if (!cap || typeof cap.getPlatform !== 'function') return 'web';
    try {
        return cap.getPlatform() || 'web';
    } catch {
        return 'web';
    }
};

/** Whether the app is running inside a native Capacitor container (Android or iOS). */
export const isCapacitorNativePlatform = (): boolean => {
    const cap = getCapacitorGlobal();
    if (!cap) return false;
    if (typeof cap.isNativePlatform === 'function') {
        try {
            return Boolean(cap.isNativePlatform());
        } catch {
            // Fall through to platform name check.
        }
    }
    const platform = getCapacitorPlatform();
    return platform === 'android' || platform === 'ios';
};

/** Whether the app is running inside the Capacitor Android native shell. */
export const isAndroidNativeApp = (): boolean => (
    isCapacitorNativePlatform() && getCapacitorPlatform() === 'android'
);

/** Whether the current browser or WebView user agent reports Android. */
export const isAndroidUserAgent = (): boolean => (
    typeof navigator !== 'undefined' && /android/i.test(navigator.userAgent)
);

/** Whether the viewport dimensions correspond to a mobile phone or compact handheld screen. */
export const isMobilePhoneViewport = (width?: number, height?: number): boolean => {
    const resolvedWidth = typeof width === 'number'
        ? width
        : (typeof window !== 'undefined' ? window.innerWidth : 1280);
    const resolvedHeight = typeof height === 'number'
        ? height
        : (typeof window !== 'undefined' ? window.innerHeight : 800);
    const shortSide = Math.min(resolvedWidth, resolvedHeight);
    return resolvedWidth <= 768 || shortSide <= 540;
};

/**
 * Determines whether the mobile-first Android player shell should be used.
 * - Always false on Electron desktop.
 * - Can be explicitly forced via URL query (`?mobile=1` or `?desktop=1`) for browser testing.
 * - True on Capacitor native Android/iOS builds and Android mobile browsers.
 */
export const shouldUseAndroidMobileShell = (options?: {
    viewportWidth?: number;
    viewportHeight?: number;
    search?: string;
}): boolean => {
    if (isElectronPlatform()) return false;

    const rawSearch = options?.search ?? (typeof window !== 'undefined' ? window.location?.search ?? '' : '');
    if (rawSearch) {
        try {
            const params = new URLSearchParams(rawSearch);
            if (params.get('desktop') === '1') return false;
            if (params.get('mobile') === '1' || params.get('android') === '1') return true;
        } catch {
            // Ignore malformed query string.
        }
    }

    if (isCapacitorNativePlatform() || isAndroidNativeApp()) {
        return true;
    }

    if (isAndroidUserAgent()) {
        return true;
    }

    return false;
};

/**
 * Whether the web PWA precache service worker should be avoided. Capacitor's Android bridge
 * injects its runtime and plugin stubs into the top-level document request; a precache service
 * worker serving cached HTML intercepts that navigation and prevents native plugin injection.
 */
export const shouldDisableWebPwaServiceWorker = (): boolean => (
    isCapacitorNativePlatform() || isElectronPlatform()
);

/**
 * The modifier a shortcut declared as `ctrl` actually uses here: Cmd on macOS, Ctrl elsewhere.
 * Shortcuts are declared once with `ctrl` and translated at the point of use, rather than each
 * declaration carrying a per-platform variant.
 */
export const isPrimaryModifierPressed = (event: KeyboardEvent): boolean => (
    isMacPlatform ? event.metaKey : event.ctrlKey
);

/** The modifier that must stay *up* for a primary-modifier shortcut to be unambiguous. */
export const isSecondaryModifierPressed = (event: KeyboardEvent): boolean => (
    isMacPlatform ? event.ctrlKey : event.metaKey
);

/** Label for the primary modifier, for shortcut hints shown in the UI. */
export const PRIMARY_MODIFIER_LABEL = isMacPlatform ? 'Cmd' : 'Ctrl';

src/utils/systemBarSettings.ts:
import {
    type FoliaAndroidSystemBarsState,
    applyAndroidSystemBarsVisibility,
} from '../services/android/foliaAndroidBridge';

// src/utils/systemBarSettings.ts
// Persisted model, screen-context resolver, and native Android bridge synchronization for
// "Display and Immersive Mode":
//   - hideStatusBar: Hide the top Android status bar across the application.
//   - hideNavigationBar: Hide the bottom Android navigation bar across the application.
//   - fullScreenLyricsMode: Hide both status and navigation bars together while viewing
//     synchronized lyrics or the full-screen visualizer, and restore the user's base
//     system-bar state when leaving full-screen lyrics/visualizer mode.

export const SYSTEM_BAR_SETTINGS_STORAGE_KEY = 'folia_system_bar_settings_v1';

export interface SystemBarSettings {
    hideStatusBar: boolean;
    hideNavigationBar: boolean;
    fullScreenLyricsMode: boolean;
}

export interface SystemBarScreenContext {
    /** Whether the user is currently viewing synchronized lyrics or full-screen visualizer/stage. */
    isLyricsOrVisualizerScreen: boolean;
}

export interface EffectiveSystemBarState {
    hideStatusBar: boolean;
    hideNavigationBar: boolean;
    isImmersiveLyricsActive: boolean;
}

export const DEFAULT_SYSTEM_BAR_SETTINGS: SystemBarSettings = {
    hideStatusBar: false,
    hideNavigationBar: false,
    fullScreenLyricsMode: false,
};

export const normalizeSystemBarSettings = (raw: unknown): SystemBarSettings => {
    if (!raw || typeof raw !== 'object') {
        return { ...DEFAULT_SYSTEM_BAR_SETTINGS };
    }
    const record = raw as Record<string, unknown>;
    return {
        hideStatusBar: Boolean(record.hideStatusBar),
        hideNavigationBar: Boolean(record.hideNavigationBar),
        fullScreenLyricsMode: Boolean(record.fullScreenLyricsMode),
    };
};

const getStorage = (): Storage | null => {
    if (typeof globalThis !== 'undefined') {
        const g = globalThis as { localStorage?: Storage; window?: { localStorage?: Storage } };
        if (g.localStorage && typeof g.localStorage.getItem === 'function') {
            return g.localStorage;
        }
        if (g.window?.localStorage && typeof g.window.localStorage.getItem === 'function') {
            return g.window.localStorage;
        }
    }
    return null;
};

export const readStoredSystemBarSettings = (): SystemBarSettings => {
    try {
        const storage = getStorage();
        const raw = storage?.getItem(SYSTEM_BAR_SETTINGS_STORAGE_KEY);
        if (!raw) {
            return { ...DEFAULT_SYSTEM_BAR_SETTINGS };
        }
        return normalizeSystemBarSettings(JSON.parse(raw));
    } catch {
        return { ...DEFAULT_SYSTEM_BAR_SETTINGS };
    }
};

export const writeStoredSystemBarSettings = (settings: SystemBarSettings): SystemBarSettings => {
    const normalized = normalizeSystemBarSettings(settings);
    try {
        const storage = getStorage();
        storage?.setItem(SYSTEM_BAR_SETTINGS_STORAGE_KEY, JSON.stringify(normalized));
    } catch {
        // Ignore storage write errors
    }
    return normalized;
};

/**
 * Computes the effective status-bar and navigation-bar visibility for the current screen.
 * When `fullScreenLyricsMode` is enabled and `isLyricsOrVisualizerScreen` is true, both system
 * bars are hidden together. When leaving the lyrics/visualizer screen, the previous base
 * `hideStatusBar` and `hideNavigationBar` preferences are restored automatically.
 */
export const resolveEffectiveSystemBars = (
    settings: SystemBarSettings,
    context: SystemBarScreenContext,
): EffectiveSystemBarState => {
    const normalized = normalizeSystemBarSettings(settings);
    const isImmersiveLyricsActive = Boolean(
        normalized.fullScreenLyricsMode && context.isLyricsOrVisualizerScreen,
    );
    return {
        hideStatusBar: isImmersiveLyricsActive ? true : normalized.hideStatusBar,
        hideNavigationBar: isImmersiveLyricsActive ? true : normalized.hideNavigationBar,
        isImmersiveLyricsActive,
    };
};

/**
 * Updates document root data attributes and safe-area CSS custom properties so the mobile shell
 * and Now Playing sheet adapt smoothly without layout jumps or flashes when system bars hide/show,
 * then dispatches the native Android WindowInsetsControllerCompat call.
 */
export const syncSystemBarsWithPlatform = async (
    effective: EffectiveSystemBarState,
): Promise<FoliaAndroidSystemBarsState> => {
    if (typeof document !== 'undefined' && document.documentElement?.dataset) {
        const root = document.documentElement;
        root.dataset.hideStatusBar = effective.hideStatusBar ? 'true' : 'false';
        root.dataset.hideNavigationBar = effective.hideNavigationBar ? 'true' : 'false';
        root.dataset.immersiveLyrics = effective.isImmersiveLyricsActive ? 'true' : 'false';
    }
    return applyAndroidSystemBarsVisibility({
        hideStatusBar: effective.hideStatusBar,
        hideNavigationBar: effective.hideNavigationBar,
    });
};

src/utils/visualizerVisibilityGate.ts:
// src/utils/visualizerVisibilityGate.ts
// Lightweight, zero-React-render visibility gate for pausing all 60/120fps requestAnimationFrame
// loops, WebGL shaders, and lyric animations immediately when the browser tab is hidden
// (`document.visibilityState === 'hidden'`) or when Android's MainActivity pauses/stops
// (`folia:native-visibility` with `{ visible: false }`, e.g. when the phone screen is turned off),
// and resuming seamlessly on wake.

export const NATIVE_VISIBILITY_EVENT_NAME = 'folia:native-visibility';

type VisibilityWindow = Window & {
    __FOLIA_NATIVE_VISIBLE__?: boolean;
};

let nativeActivityVisible = true;
let listenersInstalled = false;
const visibilityListeners = new Set<(visible: boolean) => void>();

const readDocumentVisible = (): boolean => {
    if (typeof document === 'undefined' || typeof document.visibilityState !== 'string') return true;
    return document.visibilityState !== 'hidden';
};

const readNativeVisible = (): boolean => {
    if (typeof window !== 'undefined') {
        const win = window as VisibilityWindow;
        if (typeof win.__FOLIA_NATIVE_VISIBLE__ === 'boolean') {
            return win.__FOLIA_NATIVE_VISIBLE__;
        }
    }
    return nativeActivityVisible;
};

export const isAppForegroundVisible = (): boolean => (
    readDocumentVisible() && readNativeVisible()
);

const notifyVisibilityListeners = () => {
    const visible = isAppForegroundVisible();
    visibilityListeners.forEach(listener => {
        try {
            listener(visible);
        } catch {
            // Ignore listener errors.
        }
    });
};

const ensureVisibilityListeners = () => {
    if (listenersInstalled || typeof window === 'undefined') {
        return;
    }
    listenersInstalled = true;

    if (typeof document !== 'undefined' && typeof document.addEventListener === 'function') {
        document.addEventListener('visibilitychange', () => {
            notifyVisibilityListeners();
        });
    }

    if (typeof window.addEventListener === 'function') {
        window.addEventListener(NATIVE_VISIBILITY_EVENT_NAME, (event: Event) => {
            const custom = event as CustomEvent<{ visible?: boolean }>;
            if (typeof custom.detail?.visible === 'boolean') {
                nativeActivityVisible = custom.detail.visible;
                (window as VisibilityWindow).__FOLIA_NATIVE_VISIBLE__ = custom.detail.visible;
                notifyVisibilityListeners();
            }
        });
    }
};

export const subscribeAppForegroundVisibility = (
    listener: (visible: boolean) => void,
): (() => void) => {
    ensureVisibilityListeners();
    visibilityListeners.add(listener);
    return () => {
        visibilityListeners.delete(listener);
    };
};

export const setNativeActivityVisibleForTests = (visible: boolean): void => {
    nativeActivityVisible = visible;
    if (typeof window !== 'undefined') {
        (window as VisibilityWindow).__FOLIA_NATIVE_VISIBLE__ = visible;
    }
    notifyVisibilityListeners();
};

src/workers/metadataParser.worker.ts:
import { parseBlob } from 'music-metadata';
import { repairFlacMetadata } from '../utils/flacMetadataRepair';
import { hasLegacyId3Tags, repairLatin1DecodedGbkText } from '../utils/legacyTagTextRepair';
import { formatLrcTimestamp } from '../utils/lyrics/lrcTimestamp';

interface ParsedLyricLine {
    text?: string;
    timestamp?: number;
}

interface ParsedLyricTag {
    id?: string;
    value?: unknown;
    text?: string;
    language?: string;
    descriptor?: string;
    syncText?: ParsedLyricLine[];
    timeStampFormat?: number;
}

interface LyricCandidate {
    text: string;
    isTranslation: boolean;
    hasTimeline: boolean;
}

interface EmbeddedMetadataResult {
    title?: string;
    artist?: string;
    artists?: string[];
    albumArtist?: string;
    album?: string;
    trackNumber?: number;
    discNumber?: number;
    year?: number;
    genre?: string;
    codec?: string;
    cover?: Blob;
    coverAssetId?: string;
    hasEmbeddedCover?: boolean;
    bitrate?: number;
    lyrics?: string;
    translationLyrics?: string;
    replayGain?: number;
    replayGainTrackGain?: number;
    replayGainTrackPeak?: number;
    replayGainAlbumGain?: number;
    replayGainAlbumPeak?: number;
    duration?: number;
}

const toHex = (bytes: Uint8Array): string => Array.from(bytes)
    .map(value => value.toString(16).padStart(2, '0'))
    .join('');

async function hashCoverBytes(bytes: BufferSource): Promise<string | undefined> {
    if (!crypto?.subtle) return undefined;
    const digest = await crypto.subtle.digest('SHA-256', bytes);
    return `sha256:${toHex(new Uint8Array(digest))}`;
}

function syncTextToLrc(syncText: ParsedLyricLine[] | undefined, timeStampFormat?: number): string | undefined {
    if (!syncText || syncText.length === 0) {
        return undefined;
    }

    if (timeStampFormat && timeStampFormat !== 2) {
        return undefined;
    }

    const lines = syncText
        .filter(line => typeof line?.timestamp === 'number' && typeof line?.text === 'string' && line.text.trim())
        .map(line => `${formatLrcTimestamp(line.timestamp!)}${line.text!.trim()}`);

    return lines.length > 0 ? `${lines.join('\n')}\n` : undefined;
}

function isTtmlLyricText(text: string): boolean {
    return /<tt(?:\s|>)/i.test(text) && (/<(?:p|body|div|span)(?:\s|>)/i.test(text) || /\bbegin\s*=/i.test(text));
}

function hasTimelineMarkers(text: string): boolean {
    return isTtmlLyricText(text)
        || /\[\d{1,2}:\d{2}(?:[.:]\d{1,3})?\]/.test(text)
        || /<\d{1,2}:\d{2}[.:]\d{2,3}>/.test(text)
        || /(?:^|\n)\s*(?:\d{2}:)?\d{2}:\d{2}\.\d{3}\s*-->/m.test(text);
}

function normalizeLyricCandidateText(text: string): string {
    return text
        .replace(/^\uFEFF/, '')
        .replace(/\u0000/g, '')
        .replace(/\r\n/g, '\n')
        .replace(/\r/g, '\n')
        .trim();
}

function hasEnhancedWordTimeline(text: string): boolean {
    return isTtmlLyricText(text)
        || /<\d{2}:\d{2}[.:]\d{2,3}>/.test(text)
        || /(?:^|\n)\s*\[\d{2}:\d{2}[.:]\d{2,3}\][^\[\]\n]+(?:\[\d{2}:\d{2}[.:]\d{2,3}\][^\[\]\n]*)+/m.test(text);
}

function chooseBestLyricCandidate(candidates: LyricCandidate[]): LyricCandidate | undefined {
    if (candidates.length === 0) {
        return undefined;
    }

    return candidates.find(candidate => hasEnhancedWordTimeline(candidate.text)) || candidates[0];
}

function isTranslationLyricTag(tag: ParsedLyricTag): boolean {
    const language = tag.language?.toLowerCase();
    const descriptor = tag.descriptor?.toLowerCase() || '';
    const id = tag.id?.toLowerCase() || '';

    return language === 'chi' ||
        language === 'zho' ||
        descriptor.includes('translation') ||
        descriptor.includes('trans') ||
        descriptor.includes('译') ||
        id.includes('translation') ||
        id.includes('trans');
}

function extractLyricText(tag: ParsedLyricTag | string): { text?: string; hasTimeline: boolean } {
    if (typeof tag === 'string') {
        const trimmed = tag.trim();
        return trimmed ? { text: trimmed, hasTimeline: hasTimelineMarkers(trimmed) } : { text: undefined, hasTimeline: false };
    }
    const directSyncText = syncTextToLrc(tag.syncText, tag.timeStampFormat);
    if (directSyncText) {
        return { text: directSyncText, hasTimeline: true };
    }

    const value = tag.value as ParsedLyricTag | string | undefined;
    if (typeof value === 'string' && value.trim()) {
        return { text: value, hasTimeline: hasTimelineMarkers(value) };
    }

    if (value && typeof value === 'object') {
        const nestedSyncText = syncTextToLrc((value as ParsedLyricTag).syncText, (value as ParsedLyricTag).timeStampFormat);
        if (nestedSyncText) {
            return { text: nestedSyncText, hasTimeline: true };
        }

        if (typeof (value as ParsedLyricTag).text === 'string' && (value as ParsedLyricTag).text!.trim()) {
            return { text: (value as ParsedLyricTag).text, hasTimeline: hasTimelineMarkers((value as ParsedLyricTag).text!) };
        }
    }

    if (typeof tag.text === 'string' && tag.text.trim()) {
        return { text: tag.text, hasTimeline: hasTimelineMarkers(tag.text) };
    }

    return { text: undefined, hasTimeline: false };
}

function getDurationFromParsedMetadata(durationSeconds?: number): number {
    if (typeof durationSeconds !== 'number' || !isFinite(durationSeconds) || durationSeconds <= 0) {
        return 0;
    }

    return Math.round(durationSeconds * 1000);
}

async function extractEmbeddedMetadata(file: File, includeCover = false): Promise<EmbeddedMetadataResult> {
    const parsingInput = await repairFlacMetadata(file, includeCover);
    const parsed = await parseBlob(parsingInput, includeCover ? undefined : { skipCovers: true });

    let originalLyric: string | undefined;
    let translationLyric: string | undefined;

    const collectLyricCandidates = (tags: ParsedLyricTag[]): LyricCandidate[] => {
        const lyricCandidates: LyricCandidate[] = [];

        const addLyricCandidate = (tag: ParsedLyricTag) => {
            const { text, hasTimeline } = extractLyricText(tag);
            if (typeof text === 'string' && text.trim()) {
                const normalizedText = normalizeLyricCandidateText(text);
                if (lyricCandidates.some(c => c.text === normalizedText)) return;
                lyricCandidates.push({
                    text: normalizedText,
                    isTranslation: isTranslationLyricTag(tag),
                    hasTimeline
                });
            }
        };

        tags.forEach(tag => addLyricCandidate(tag));
        return lyricCandidates;
    };

    const commonCandidates = collectLyricCandidates((parsed.common.lyrics || []) as ParsedLyricTag[]);

    let lyricCandidates = commonCandidates;
    if (lyricCandidates.length === 0) {
        const nativeLyricTags: ParsedLyricTag[] = [];
        for (const tags of Object.values(parsed.native || {})) {
            (tags as ParsedLyricTag[]).forEach(tag => {
                const id = tag.id?.toLowerCase() || '';
                if (id.includes('lyric') || id.includes('lyr') || id.includes('uslt') || id.includes('sylt') || id.includes('ttml')) {
                    nativeLyricTags.push(tag);
                }
            });
        }
        lyricCandidates = collectLyricCandidates(nativeLyricTags);
    }

    if (lyricCandidates.length > 0) {
        const withTimeline = lyricCandidates.filter(c => c.hasTimeline);
        const source = withTimeline.length > 0 ? withTimeline : lyricCandidates;
        const translationCandidates = source.filter(c => c.isTranslation);
        const originalCandidates = source.filter(c => !c.isTranslation);

        const bestOriginal = chooseBestLyricCandidate(originalCandidates) || chooseBestLyricCandidate(source);
        const bestTranslation = chooseBestLyricCandidate(
            translationCandidates.filter(candidate => candidate.text !== bestOriginal?.text)
        );

        originalLyric = bestOriginal?.text;
        translationLyric = bestTranslation?.text;
    }

    const replayGainTrackTag = parsed.common.replaygain_track_gain;
    const replayGainTrackPeakTag = parsed.common.replaygain_track_peak;
    const replayGainAlbumTag = parsed.common.replaygain_album_gain;
    const replayGainAlbumPeakTag = parsed.common.replaygain_album_peak;

    const replayGainTrackDb = typeof replayGainTrackTag?.dB === 'number'
        ? replayGainTrackTag.dB
        : parsed.format.trackGain;
    const replayGainTrackPeak = typeof replayGainTrackPeakTag?.ratio === 'number'
        ? replayGainTrackPeakTag.ratio
        : parsed.format.trackPeakLevel;
    const replayGainAlbumDb = typeof replayGainAlbumTag?.dB === 'number'
        ? replayGainAlbumTag.dB
        : parsed.format.albumGain;
    const replayGainAlbumPeak = typeof replayGainAlbumPeakTag?.ratio === 'number'
        ? replayGainAlbumPeakTag.ratio
        : undefined;

    const picture = includeCover ? parsed.common.picture?.[0] : undefined;
    const cover = picture
        ? new Blob([picture.data as any], { type: picture.format })
        : undefined;
    const coverAssetId = picture ? await hashCoverBytes(Uint8Array.from(picture.data)) : undefined;

    const repairTagText = hasLegacyId3Tags(parsed.format.tagTypes)
        ? (text: string | undefined) => (text ? repairLatin1DecodedGbkText(text) : text)
        : (text: string | undefined) => text;

    return {
        title: repairTagText(parsed.common.title),
        artist: repairTagText(parsed.common.artist),
        artists: parsed.common.artists?.map(artist => repairTagText(artist) ?? artist),
        albumArtist: repairTagText(parsed.common.albumartist),
        album: repairTagText(parsed.common.album),
        trackNumber: parsed.common.track.no ?? undefined,
        discNumber: parsed.common.disk.no ?? undefined,
        year: parsed.common.year ?? undefined,
        genre: parsed.common.genre?.[0] ? repairTagText(parsed.common.genre[0]) : undefined,
        codec: parsed.format.codec || parsed.format.container || undefined,
        cover,
        coverAssetId,
        hasEmbeddedCover: includeCover ? Boolean(picture) : undefined,
        bitrate: parsed.format.bitrate,
        lyrics: originalLyric,
        translationLyrics: translationLyric,
        replayGain: replayGainTrackDb,
        replayGainTrackGain: replayGainTrackDb,
        replayGainTrackPeak,
        replayGainAlbumGain: replayGainAlbumDb,
        replayGainAlbumPeak,
        duration: getDurationFromParsedMetadata(parsed.format.duration)
    };
}

self.onmessage = async (e: MessageEvent) => {
    const { type, file, cover, includeCover, requestId } = e.data as {
        type: string;
        file?: File;
        cover?: Blob;
        includeCover?: boolean;
        requestId: string;
    };

    if (type !== 'parse-metadata' && type !== 'hash-cover') {
        self.postMessage({ type: 'error', message: 'Unknown message type', requestId });
        return;
    }

    try {
        if (type === 'hash-cover') {
            if (!(cover instanceof Blob) || cover.size === 0 || !cover.type.startsWith('image/')) {
                throw new Error('Invalid local cover payload');
            }
            const coverAssetId = await hashCoverBytes(await cover.arrayBuffer());
            if (!coverAssetId) throw new Error('Web Crypto SHA-256 is unavailable');
            self.postMessage({ type: 'result', data: { cover, coverAssetId }, requestId });
            return;
        }

        if (!(file instanceof File)) throw new Error('Missing metadata file');
        const data = await extractEmbeddedMetadata(file, Boolean(includeCover));
        self.postMessage({ type: 'result', data, requestId });
    } catch (err) {
        self.postMessage({ type: 'error', message: String(err), requestId });
    }
};

