                const rel = `${folder}/${fileName}`;
                const fileSize = 27_000_000; // ~25.75 MiB per FLAC -> 800 * 27 MB = 21.60 GB (> 20 GiB)
                totalLibraryBytes += fileSize;
                entries.push({
                    name: fileName,
                    relativePath: rel,
                    kind: 'file',
                    documentId: `primary:Music/${rel}`,
                    contentUri: `content://saf/${rel}`,
                    mimeType: 'audio/flac',
