import { clamp01 } from './filmGateMotion';
import type { FilmGateAudioFrame } from './filmGateAudio';
import type { FilmgateTuning } from './types';

// src/components/visualizer/filmgate/filmGateAtmosphere.ts
// The film environment, drawn with plain Canvas2D from a few reused resources: a warm projector beam, edge light
// leaks, rare exposure sweeps, bass ripples, fine grain from pre-made noise tiles, bounded floating dust, rare scratches,
// and the film-frame marks. Everything is a function of the clock and the smoothed audio, with a fixed seed, so it
// looks the same on every run and in an exported video. Nothing is allocated per frame.

const TAU = Math.PI * 2;
const GRAIN_TILE = 96;
const GRAIN_TILES = 4;
const MAX_DUST = 36;
const MAX_RIPPLES = 3;

// A small deterministic generator: the same song always gets the same dust.
const seeded = (seed: number) => {
    let state = seed >>> 0;
    return () => {
        state = (state + 0x6d2b79f5) >>> 0;
        let t = state;
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
};

export interface FilmAtmosphereQuality {
    /** 0..1: scales dust count and grain redraw rate. */
    detail: number;
}

interface Dust {
    x: number; y: number; size: number; speed: number; sway: number; phase: number; glint: number;
}

export interface FilmAtmosphere {
    /** Everything behind the lyrics: grade, beam, leaks, ripples, dust, grain, scratches. */
    drawBack: (ctx: CanvasRenderingContext2D, w: number, h: number, clock: number, audio: FilmGateAudioFrame, tuning: FilmgateTuning, motion: number, shotLeak: number) => void;
    /** Everything in front: frame marks and vignette. */
    drawFront: (ctx: CanvasRenderingContext2D, w: number, h: number, clock: number, audio: FilmGateAudioFrame, tuning: FilmgateTuning, motion: number) => void;
    dispose: () => void;
}

const makeGrainTiles = (): HTMLCanvasElement[] => {
    const rand = seeded(20260511);
    const tiles: HTMLCanvasElement[] = [];
    for (let k = 0; k < GRAIN_TILES; k += 1) {
        const canvas = document.createElement('canvas');
        canvas.width = GRAIN_TILE;
        canvas.height = GRAIN_TILE;
        const ctx = canvas.getContext('2d');
        if (ctx) {
            const image = ctx.createImageData(GRAIN_TILE, GRAIN_TILE);
            for (let i = 0; i < image.data.length; i += 4) {
                const v = rand() < 0.5 ? 255 : 0;
                image.data[i] = v; image.data[i + 1] = v; image.data[i + 2] = v;
                image.data[i + 3] = Math.floor(rand() * 255);
            }
            ctx.putImageData(image, 0, 0);
        }
        tiles.push(canvas);
    }
    return tiles;
};

export const createFilmAtmosphere = (seedNumber: number, quality: FilmAtmosphereQuality): FilmAtmosphere => {
    const rand = seeded(seedNumber || 1);
    const dustCount = Math.max(8, Math.round(MAX_DUST * clamp01(quality.detail)));
    const dust: Dust[] = Array.from({ length: dustCount }, () => ({
        x: rand(), y: rand(), size: 0.6 + rand() * 1.6, speed: 0.004 + rand() * 0.012, sway: 0.01 + rand() * 0.03, phase: rand() * TAU, glint: rand(),
    }));
    const tiles = makeGrainTiles();
    const patterns = new WeakMap<CanvasRenderingContext2D, CanvasPattern[]>();
    const ripples = new Float64Array(MAX_RIPPLES).fill(-100);
    let rippleCursor = 0;
    let kickWasHigh = false;

    const patternsFor = (ctx: CanvasRenderingContext2D) => {
        let list = patterns.get(ctx);
        if (!list) {
            list = tiles.map(tile => ctx.createPattern(tile, 'repeat')).filter((p): p is CanvasPattern => p !== null);
            patterns.set(ctx, list);
        }
        return list;
    };

    const drawBack: FilmAtmosphere['drawBack'] = (ctx, w, h, clock, audio, tuning, motion, shotLeak) => {
        const minSide = Math.min(w, h);
        // Natural exposure fluctuation: slow, small.
        const flicker = 1 + 0.03 * Math.sin(clock * 7.3) * Math.sin(clock * 1.9 + 0.6);
        const energy = 0.35 + 0.65 * audio.power;
        // Deep cinematic black, a little transparent so the song's own background still breathes through.
        ctx.fillStyle = 'rgba(7,6,5,0.86)';
        ctx.fillRect(0, 0, w, h);

        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        // Projector beam: a warm cone from above the frame, wider and brighter with the music.
        const bx = w * 0.5 + Math.sin(clock * 0.21) * w * 0.02 * motion;
        const by = -h * 0.18;
        const beam = ctx.createRadialGradient(bx, by, minSide * 0.05, bx, h * 0.5, Math.max(w, h) * 0.78);
        const beamAlpha = (0.085 + 0.07 * energy + 0.05 * audio.lowMid) * flicker;
        beam.addColorStop(0, `rgba(255,190,110,${(beamAlpha * 1.5).toFixed(3)})`);
        beam.addColorStop(0.45, `rgba(214,142,70,${(beamAlpha * 0.55).toFixed(3)})`);
        beam.addColorStop(1, 'rgba(120,70,30,0)');
        ctx.fillStyle = beam;
        ctx.fillRect(0, 0, w, h);

        // Light leaks from the frame edges.
        const leakAmount = tuning.lightLeaks;
        if (leakAmount > 0.001) {
            const base = 0.07 * leakAmount * (0.55 + 0.45 * audio.lowMid + 0.3 * audio.power) + 0.16 * shotLeak * leakAmount;
            const lx = (Math.sin(clock * 0.13) * 0.5 + 0.5) * 0.35;
            const left = ctx.createRadialGradient(w * lx, h * 0.62, 0, w * lx, h * 0.62, minSide * 0.8);
            left.addColorStop(0, `rgba(255,120,48,${(base * 0.9).toFixed(3)})`);
            left.addColorStop(1, 'rgba(120,30,10,0)');
            ctx.fillStyle = left;
            ctx.fillRect(0, 0, w, h);
            const rx = 1 - (Math.sin(clock * 0.11 + 2.1) * 0.5 + 0.5) * 0.3;
            const right = ctx.createRadialGradient(w * rx, h * 0.28, 0, w * rx, h * 0.28, minSide * 0.7);
            right.addColorStop(0, `rgba(190,70,40,${(base * 0.7).toFixed(3)})`);
            right.addColorStop(1, 'rgba(90,20,10,0)');
            ctx.fillStyle = right;
            ctx.fillRect(0, 0, w, h);

            // A rare exposure sweep: a soft diagonal band every ~23 s, about 2 s long.
            const cycle = clock % 23;
            if (cycle < 2.2) {
                const p = cycle / 2.2;
                const fade = Math.sin(p * Math.PI);
                const x = -w * 0.3 + p * w * 1.6;
                const band = ctx.createLinearGradient(x - w * 0.18, 0, x + w * 0.18, h * 0.35);
                band.addColorStop(0, 'rgba(255,230,190,0)');
                band.addColorStop(0.5, `rgba(255,226,180,${(0.09 * fade * leakAmount).toFixed(3)})`);
                band.addColorStop(1, 'rgba(255,230,190,0)');
                ctx.fillStyle = band;
                ctx.fillRect(0, 0, w, h);
            }
        }

        // Bass ripple: a ring of exposure travelling out from the beam origin on each strong kick.
        const kickHigh = audio.kick > 0.5;
        if (kickHigh && !kickWasHigh && tuning.impact > 0.001) {
            ripples[rippleCursor] = clock;
            rippleCursor = (rippleCursor + 1) % MAX_RIPPLES;
        }
        kickWasHigh = kickHigh;
        if (tuning.impact > 0.001) {
            for (let i = 0; i < MAX_RIPPLES; i += 1) {
                const age = clock - ripples[i]!;
                if (age < 0 || age > 1.1) continue;
                const radius = minSide * (0.12 + age * 0.85);
                const alpha = (1 - age / 1.1) ** 2 * 0.09 * tuning.impact;
                const ring = ctx.createRadialGradient(bx, h * 0.42, radius * 0.86, bx, h * 0.42, radius);
                ring.addColorStop(0, 'rgba(255,200,130,0)');
                ring.addColorStop(1, `rgba(255,205,140,${alpha.toFixed(3)})`);
                ctx.fillStyle = ring;
                ctx.fillRect(0, 0, w, h);
            }
        }

        // Dust: drifts upward in the beam; the treble makes some of it catch the light.
        for (let i = 0; i < dust.length; i += 1) {
            const d = dust[i]!;
            const y = ((d.y - clock * d.speed * (0.4 + 0.6 * motion)) % 1 + 1) % 1;
            const x = d.x + Math.sin(clock * 0.4 + d.phase) * d.sway * motion;
            const inBeam = 1 - Math.min(1, Math.abs(x - 0.5) * 1.7);
            const glint = d.glint > 0.7 ? audio.treble * 0.9 : 0;
            const alpha = (0.1 + 0.28 * inBeam + glint) * (0.55 + 0.45 * Math.sin(clock * 0.8 + d.phase) ** 2);
            if (alpha < 0.02) continue;
            ctx.fillStyle = `rgba(255,222,170,${Math.min(0.75, alpha).toFixed(3)})`;
            ctx.beginPath();
            ctx.arc(x * w, y * h, d.size * (minSide / 700) * (1 + glint), 0, TAU);
            ctx.fill();
        }
        ctx.restore();

        // Grain: pre-made noise tiles, offset every few frames; never drawn over the lyrics (they come after).
        if (tuning.grain > 0.001) {
            const list = patternsFor(ctx);
            if (list.length > 0) {
                const step = Math.floor(clock * (motion > 0 ? 18 : 0));
                const pattern = list[step % list.length]!;
                const ox = ((step * 37) % GRAIN_TILE);
                const oy = ((step * 53) % GRAIN_TILE);
                ctx.save();
                ctx.globalAlpha = 0.05 * tuning.grain;
                ctx.translate(-ox, -oy);
                ctx.fillStyle = pattern;
                ctx.fillRect(0, 0, w + GRAIN_TILE, h + GRAIN_TILE);
                ctx.restore();
            }
        }

        // Rare tiny scratches: one thin vertical hairline for a moment every few seconds.
        if (motion > 0 && tuning.grain > 0.001) {
            const slot = Math.floor(clock / 3.7);
            const local = clock - slot * 3.7;
            if (local < 0.11 && (slot * 2654435761 >>> 0) % 5 < 2) {
                const x = ((((slot * 40503) >>> 0) % 1000) / 1000) * w;
                ctx.fillStyle = 'rgba(255,238,210,0.12)';
                ctx.fillRect(x, h * 0.08, Math.max(1, minSide / 900), h * 0.84);
            }
        }
    };

    const drawFront: FilmAtmosphere['drawFront'] = (ctx, w, h, clock, audio, tuning, motion) => {
        const minSide = Math.min(w, h);
        if (tuning.frame) {
            const inset = Math.round(minSide * 0.045);
            const arm = Math.round(minSide * 0.045);
            ctx.save();
            ctx.strokeStyle = 'rgba(214,170,110,0.34)';
            ctx.lineWidth = Math.max(1, minSide / 700);
            // Corner marks.
            ctx.beginPath();
            const corners: Array<[number, number, number, number]> = [[inset, inset, 1, 1], [w - inset, inset, -1, 1], [inset, h - inset, 1, -1], [w - inset, h - inset, -1, -1]];
            for (const [x, y, sx, sy] of corners) {
                ctx.moveTo(x + sx * arm, y);
                ctx.lineTo(x, y);
                ctx.lineTo(x, y + sy * arm);
            }
            ctx.stroke();
            // Thin frame guides along the middle of each side.
            ctx.strokeStyle = 'rgba(214,170,110,0.16)';
            ctx.beginPath();
            ctx.moveTo(w / 2 - arm * 0.5, inset); ctx.lineTo(w / 2 + arm * 0.5, inset);
            ctx.moveTo(w / 2 - arm * 0.5, h - inset); ctx.lineTo(w / 2 + arm * 0.5, h - inset);
            ctx.moveTo(inset, h / 2 - arm * 0.5); ctx.lineTo(inset, h / 2 + arm * 0.5);
            ctx.moveTo(w - inset, h / 2 - arm * 0.5); ctx.lineTo(w - inset, h / 2 + arm * 0.5);
            ctx.stroke();
            // Sprocket holes along the outer edges: a slow frame-advance crawl, kept to a thin margin.
            if (w >= 360) {
                const hole = Math.max(3, minSide * 0.011);
                const pitch = hole * 3.4;
                const crawl = (clock * hole * 0.9 * motion + Math.floor(audio.kick * 2) * 0) % pitch;
                ctx.fillStyle = 'rgba(214,170,110,0.13)';
                for (let y = -pitch + crawl; y < h; y += pitch) {
                    ctx.fillRect(inset * 0.35, y, hole, hole * 1.4);
                    ctx.fillRect(w - inset * 0.35 - hole, y, hole, hole * 1.4);
                }
            }
            ctx.restore();
        }
        // Vignette.
        const vignette = ctx.createRadialGradient(w / 2, h / 2, minSide * 0.35, w / 2, h / 2, Math.max(w, h) * 0.75);
        vignette.addColorStop(0, 'rgba(0,0,0,0)');
        vignette.addColorStop(1, 'rgba(0,0,0,0.55)');
        ctx.fillStyle = vignette;
        // Larger than the stage: the gate transform may shift it a little and no edge sliver may show.
        ctx.fillRect(-w * 0.05, -h * 0.05, w * 1.1, h * 1.1);
    };

    return { drawBack, drawFront, dispose: () => { ripples.fill(-100); } };
};

import type { MotionValue } from 'framer-motion';
import type { AudioBands } from '../../../types';

// src/components/visualizer/filmgate/filmGateAudio.ts
// Folia's audio MotionValues -> the few smoothed 0..1 signals FILMGATE draws from.
//
// Scale: the main player writes 0..255 (and a 0..40 "breathing" while silent); the playground, previews and the OBS
// bridge write 0..1. A source never mixes the two, so, as the other styles do, the first value seen above 1 pins the
// source as 0..255 (looking at the current value alone would read a quiet 0.3 of a 0..255 source as 0.3, not 0.001).
// The video exporter feeds only the overall level (bands are zero), so then the bands are derived from it.
// Smoothing: fast attack, slow release, independent per channel; paused reads as silence.

export interface FilmGateAudioFrame {
    bass: number;
    lowMid: number;
    /** Mid and vocal bands together. */
    mid: number;
    treble: number;
    power: number;
    /** A short 0..1 pulse that jumps when the bass rises sharply and decays in about 0.35 s. */
    kick: number;
}

export interface FilmGateAudioSources {
    audioPower: MotionValue<number>;
    audioBands: AudioBands;
}

export const normalizeFilmGateValue = (value: number, rawScale: boolean) => {
    if (!Number.isFinite(value) || value <= 0) return 0;
    return Math.min(1, rawScale ? value / 255 : value);
};

const smooth = (current: number, target: number, dt: number, attack: number, release: number) => {
    const tau = target > current ? attack : release;
    return current + (target - current) * (1 - Math.exp(-Math.max(0, dt) / tau));
};

export interface FilmGateAudioSampler {
    readonly frame: FilmGateAudioFrame;
    sample: (dt: number, paused: boolean) => void;
    setSources: (sources: FilmGateAudioSources) => void;
}

export const createFilmGateAudioSampler = (initial: FilmGateAudioSources): FilmGateAudioSampler => {
    let sources = initial;
    let rawScale = false;
    let bassAverage = 0;
    const frame: FilmGateAudioFrame = { bass: 0, lowMid: 0, mid: 0, treble: 0, power: 0, kick: 0 };
    const read = (value: MotionValue<number> | undefined) => {
        const raw = value?.get() ?? 0;
        if (raw > 1) rawScale = true;
        return raw;
    };
    return {
        frame,
        setSources: next => {
            if (next.audioPower === sources.audioPower && next.audioBands === sources.audioBands) return;
            sources = next;
            rawScale = false;
        },
        sample: (dt, paused) => {
            if (paused) {
                frame.bass = frame.lowMid = frame.mid = frame.treble = frame.power = 0;
                frame.kick = smooth(frame.kick, 0, dt, 0.05, 0.2);
                bassAverage = 0;
                return;
            }
            const b = sources.audioBands;
            const rawPower = read(sources.audioPower);
            const rawBands = [read(b.bass), read(b.lowMid), Math.max(read(b.mid), read(b.vocal)), read(b.treble)];
            const power = normalizeFilmGateValue(rawPower, rawScale);
            const hasBands = rawBands.some(value => value > 0);
            const bands = hasBands
                ? rawBands.map(value => normalizeFilmGateValue(value, rawScale))
                // Only the overall level is known (video export): spread it over the bands in a plausible way.
                : [power * 0.9, power * 0.7, power * 0.6, power * 0.4];
            frame.bass = smooth(frame.bass, bands[0]!, dt, 0.05, 0.28);
            frame.lowMid = smooth(frame.lowMid, bands[1]!, dt, 0.08, 0.35);
            frame.mid = smooth(frame.mid, bands[2]!, dt, 0.07, 0.3);
            frame.treble = smooth(frame.treble, bands[3]!, dt, 0.04, 0.22);
            frame.power = smooth(frame.power, power, dt, 0.12, 0.5);
            // A kick is the bass jumping above its own slow average.
            const jump = Math.max(0, bands[0]! - bassAverage - 0.08);
            bassAverage = smooth(bassAverage, bands[0]!, dt, 0.35, 0.35);
            const hit = Math.min(1, jump * 3.2);
            frame.kick = hit > frame.kick ? hit : smooth(frame.kick, 0, dt, 0.05, 0.35);
        },
    };
};

import type { Line } from '../../../types';
import {
    containsArabicText, detectTextDirection, mergeContiguousArabicWordsInLine, orderBidiItemsForVisualRow,
    resolveTokenDirection, type TextDirection,
} from '../../../utils/lyrics/arabicText';
import { segmentLyricWords } from '../../../utils/lyrics/wordSegmentation';

// src/components/visualizer/filmgate/filmGateLayout.ts
// A lyric line -> timed whole words -> wrapped, bidi-ordered rows. Pure: text is measured through a callback so the
// layout runs the same in a test as on the canvas. Arabic stays in whole words: a word is one unit with the TTML
// timestamps the line already has (contiguous Arabic pieces are merged by mergeContiguousArabicWordsInLine, the same
// helper the other styles use), and it is drawn with ONE fillText call, so the browser's own shaping keeps the
// contextual forms, the joining and the diacritics. Nothing here ever splits a word into letters.

export interface FilmWord {
    text: string;
    start: number;
    end: number;
    dir: TextDirection;
}

export interface PlacedWord {
    word: FilmWord;
    /** Left edge of the word inside its row, row-relative (the row is centred by the caller). */
    x: number;
    width: number;
}

export interface FilmRow {
    words: PlacedWord[];
    width: number;
}

export interface FilmLayout {
    rows: FilmRow[];
    direction: TextDirection;
    /** Whole-line width of the widest row. */
    width: number;
    lineHeight: number;
    /** Font size the layout was made at, in px (the caller shrinks long lines). */
    fontSize: number;
}

/** The line's words with their times. Per-word timestamps are used as they are; a line without them is spread over its own span by letter count. */
export const buildFilmWords = (line: Line): FilmWord[] => {
    const baseDirection = detectTextDirection(line.fullText);
    const merged = containsArabicText(line.fullText) ? mergeContiguousArabicWordsInLine(line) : line;
    const timed = merged.words
        .filter(word => word.text.trim().length > 0 && Number.isFinite(word.startTime) && Number.isFinite(word.endTime))
        .map(word => ({ text: word.text.trim(), start: word.startTime, end: Math.max(word.endTime, word.startTime) }));
    const segments = segmentLyricWords(line).filter(segment => segment.isWordLike && segment.segment.trim().length > 0);
    const useTimed = timed.length > 1 || (timed.length === 1 && segments.length <= 1);
    if (useTimed) {
        return timed.map(word => ({ ...word, dir: resolveTokenDirection(word.text, baseDirection) }));
    }
    const source = segments.length > 0 ? segments.map(segment => segment.segment.trim()) : [line.fullText.trim()].filter(Boolean);
    const total = source.reduce((sum, text) => sum + Array.from(text).length, 0) || 1;
    const span = Math.max(0.1, line.endTime - line.startTime);
    let cursor = line.startTime;
    return source.map(text => {
        const share = (Array.from(text).length / total) * span;
        const word = { text, start: cursor, end: cursor + share, dir: resolveTokenDirection(text, baseDirection) };
        cursor += share;
        return word;
    });
};

export interface FilmLayoutInput {
    words: readonly FilmWord[];
    direction: TextDirection;
    maxWidth: number;
    spaceWidth: number;
    lineHeight: number;
    measure: (text: string) => number;
}

/** Greedy wrap in reading order, then each row in visual left-to-right order by the Unicode bidi rule the other styles use. */
export const layoutFilmLine = (input: FilmLayoutInput): FilmLayout => {
    const { words, direction, maxWidth, spaceWidth, lineHeight, measure } = input;
    const widths = words.map(word => measure(word.text));
    const groups: number[][] = [];
    let current: number[] = [];
    let used = 0;
    words.forEach((_, index) => {
        const next = used + (current.length ? spaceWidth : 0) + widths[index]!;
        if (current.length > 0 && next > maxWidth) {
            groups.push(current);
            current = [];
            used = 0;
        }
        used += (current.length ? spaceWidth : 0) + widths[index]!;
        current.push(index);
    });
    if (current.length) groups.push(current);
    const rows: FilmRow[] = groups.map(group => {
        const ordered = orderBidiItemsForVisualRow(group, index => words[index]!.text, direction);
        let x = 0;
        const placed = ordered.map((index, slot) => {
            if (slot > 0) x += spaceWidth;
            const item: PlacedWord = { word: words[index]!, x, width: widths[index]! };
            x += widths[index]!;
            return item;
        });
        return { words: placed, width: x };
    });
    return { rows, direction, width: Math.max(0, ...rows.map(row => row.width)), lineHeight, fontSize: 0 };
};

// src/components/visualizer/filmgate/filmGateMotion.ts
// FILMGATE's motion as pure functions of song time: how a word is lit, how a line enters and leaves like a shot change,
// and how the gate moves. Nothing here reads a clock or random numbers, so a paused or exported frame is exactly the
// frame the player showed.

export const clamp01 = (value: number) => (value < 0 ? 0 : value > 1 ? 1 : value);
export const easeOut = (value: number) => 1 - (1 - clamp01(value)) ** 3;
export const easeInOut = (value: number) => {
    const x = clamp01(value);
    return x < 0.5 ? 4 * x * x * x : 1 - (-2 * x + 2) ** 3 / 2;
};

/** Brightness an upcoming word sits at, and the level a finished word settles to. */
export const WORD_UPCOMING = 0.2;
export const WORD_SETTLED = 0.58;
/** How long before its start a word begins to emerge, and how long a finished word takes to settle. */
export const WORD_LEAD = 0.3;
export const WORD_SETTLE = 1.5;
const MIN_ACTIVE = 0.14;

export interface WordLight {
    /** 0..1 brightness of the word. */
    exposure: number;
    /** 0..1 position of the warm light sweep across the word, in reading direction. */
    sweep: number;
    /** 0..1 glow around the edges. */
    glow: number;
    /** Rise of the word into place: 0 = fully risen. In em. */
    rise: number;
    /** 0.96..1 scale as the word settles. */
    scale: number;
}

export const wordLight = (time: number, start: number, end: number): WordLight => {
    const finish = Math.max(end, start + MIN_ACTIVE);
    const duration = finish - start;
    if (time < start - WORD_LEAD) return { exposure: WORD_UPCOMING, sweep: 0, glow: 0, rise: 0.06, scale: 0.97 };
    if (time < start) {
        const k = easeOut((time - (start - WORD_LEAD)) / WORD_LEAD);
        return { exposure: WORD_UPCOMING + (0.42 - WORD_UPCOMING) * k, sweep: 0, glow: 0, rise: 0.06 * (1 - k), scale: 0.97 + 0.02 * k };
    }
    if (time <= finish) {
        const p = (time - start) / duration;
        const settle = easeOut((time - start) / Math.min(0.35, duration));
        return {
            exposure: 0.42 + 0.58 * easeOut(Math.min(1, p * 1.6)),
            sweep: p,
            glow: 0.55 + 0.45 * Math.sin(Math.min(1, p) * Math.PI * 0.5),
            rise: 0,
            scale: 0.99 + 0.01 * settle,
        };
    }
    const after = time - finish;
    const k = easeInOut(after / WORD_SETTLE);
    return { exposure: 1 - (1 - WORD_SETTLED) * k, sweep: 1, glow: Math.max(0, 1 - after / 0.9) * 0.8, rise: 0, scale: 1 };
};

export type ShotKind = 'push' | 'pull' | 'advance' | 'focus' | 'leak' | 'dissolve';
const SHOT_KINDS: readonly ShotKind[] = ['push', 'dissolve', 'advance', 'focus', 'pull', 'leak'];

/** Deterministic shot for a line: the same line always gets the same cut, and neighbours differ. */
export const shotKindFor = (lineIndex: number): ShotKind => SHOT_KINDS[((lineIndex % SHOT_KINDS.length) + SHOT_KINDS.length) % SHOT_KINDS.length]!;

export const SHOT_IN = 0.45;
export const SHOT_OUT_HOLD = 0.5;
export const SHOT_OUT = 0.7;

export interface ShotFrame {
    visible: boolean;
    alpha: number;
    scale: number;
    /** Vertical offset as a fraction of the stage height. */
    dy: number;
    /** Optical defocus in CSS px at a 1000px stage. */
    blur: number;
    /** 0..1 light-leak flare tied to this cut. */
    leak: number;
}

/** A line's shot at `time`. The line is on screen from SHOT_IN before it starts until it has been out for SHOT_OUT. */
export const shotFrame = (time: number, lineStart: number, lineEnd: number, kind: ShotKind, nextCutAt?: number): ShotFrame => {
    const inStart = lineStart - SHOT_IN;
    // When the next line is already coming the old one leaves earlier and quicker, so two lines are never both full on screen.
    const outStart = nextCutAt === undefined ? lineEnd + SHOT_OUT_HOLD : Math.max(lineStart, Math.min(lineEnd + SHOT_OUT_HOLD, nextCutAt - 0.2));
    const outSpan = nextCutAt === undefined ? SHOT_OUT : Math.min(SHOT_OUT, Math.max(0.25, nextCutAt + 0.1 - outStart));
    if (time < inStart || time > outStart + outSpan) return { visible: false, alpha: 0, scale: 1, dy: 0, blur: 0, leak: 0 };
    const enter = easeInOut((time - inStart) / SHOT_IN);
    const exit = easeInOut((time - outStart) / outSpan);
    const span = Math.max(0.5, lineEnd - lineStart);
    const drift = clamp01((time - lineStart) / span);
    let alpha = enter * (1 - exit);
    let scale = 1;
    let dy = 0;
    let blur = 0;
    let leak = 0;
    switch (kind) {
        case 'push': scale = 0.965 + 0.035 * enter + 0.03 * drift + 0.03 * exit; break;
        case 'pull': scale = 1.05 - 0.05 * enter + 0.01 * drift - 0.02 * exit; break;
        case 'advance': dy = (1 - enter) * 0.045 - exit * 0.045; scale = 1 + 0.015 * drift; break;
        case 'focus': blur = (1 - enter) * 7 + exit * 4; scale = 1.01 + 0.015 * drift; break;
        case 'leak': scale = 0.985 + 0.015 * enter + 0.015 * drift; leak = Math.sin(Math.min(1, enter) * Math.PI) * (1 - exit); break;
        case 'dissolve': scale = 1 + 0.012 * drift; alpha = enter * (1 - exit) ** 1.4; break;
    }
    dy -= exit * 0.03;
    return { visible: alpha > 0.002, alpha, scale, dy, blur, leak };
};

export interface GateOffset {
    dx: number;
    dy: number;
    rotation: number;
    /** 1 = at rest, below 1 = the gate compressed by a kick. */
    squeeze: number;
}

/** The gate's slow mechanical wander plus the kick's impact, as fractions of the stage size. `motion` is gateMotion * reduced-motion factor. */
export const gateOffset = (clock: number, motion: number, kick: number, impact: number, lowMid: number): GateOffset => {
    const m = Math.max(0, motion);
    const amp = (0.0016 + 0.0016 * clamp01(lowMid)) * m;
    return {
        dx: amp * (Math.sin(clock * 0.61) + 0.5 * Math.sin(clock * 1.7 + 1.3)),
        dy: amp * (Math.sin(clock * 0.47 + 0.4) + 0.5 * Math.sin(clock * 2.1)) + 0.006 * clamp01(kick) * impact * (m > 0 ? 1 : 0.4),
        rotation: 0.0016 * m * Math.sin(clock * 0.37),
        squeeze: 1 - 0.012 * clamp01(kick) * impact,
    };
};

